function questionsPage(){return `${heading(state.role==='teacher'?'Ngân hàng câu hỏi':'Quản lý câu hỏi','Câu hỏi trắc nghiệm và tự luận theo từng bài học.',state.role==='teacher'?`<div class="d-flex gap-2"><button class="btn btn-light" data-page="generator">Tạo bằng AI</button><button class="btn btn-primary" data-modal="question">＋ Tạo câu hỏi</button></div>`:'')}<div class="cardx card-pad mb-3"><div class="filter-row"><input class="form-control" style="max-width:260px" placeholder="Tìm câu hỏi..."><select class="form-select" style="width:180px"><option>Tất cả chủ đề</option>${topicNames.map(t=>`<option>${t}</option>`).join('')}</select><select class="form-select" style="width:160px"><option>Mọi loại câu hỏi</option><option>Trắc nghiệm</option><option>Tự luận</option></select><select class="form-select" style="width:150px"><option>Mọi trạng thái</option><option>Chờ duyệt</option><option>Đã xuất bản</option></select></div></div><div class="cardx"><div class="table-responsive"><table class="table"><thead><tr><th>Nội dung</th><th>Chủ đề</th><th>Loại</th><th>Độ khó</th><th>Nguồn</th><th>Trạng thái</th><th></th></tr></thead><tbody>${[['Trục đối xứng của parabol y = 2x² − 4x + 1?','Hàm số','Trắc nghiệm','Cơ bản','AI','Chờ duyệt'],['Tìm tập xác định của hàm số phân thức...','Tập hợp','Tự luận','Trung bình','Giáo viên','Đã xuất bản'],['Giải hệ bất phương trình bậc nhất...','Bất phương trình','Trắc nghiệm','Nâng cao','AI','Chờ duyệt'],['Tính sin góc A khi biết các cạnh...','Hệ thức lượng','Tự luận','Trung bình','Giáo viên','Đã xuất bản']].map((q,i)=>`<tr><td style="max-width:260px"><strong>${q[0]}</strong><div class="tiny muted">Cập nhật ${i+1} ngày trước</div></td><td>${q[1]}</td><td><span class="tag ${q[2]==='Tự luận'?'tag-purple':'tag-blue'}">${q[2]}</span></td><td>${q[3]}</td><td>${q[4]}</td><td><span class="tag ${q[5]==='Chờ duyệt'?'tag-orange':'tag-green'}">${q[5]}</span></td><td>${q[5]==='Chờ duyệt'?`<button class="btn btn-soft btn-sm" data-action="approve">Duyệt</button>`:`<button class="btn btn-light btn-sm">Sửa</button>`}</td></tr>`).join('')}</tbody></table></div></div>`}
function generatorPage(){return `${heading('Tạo câu hỏi bằng AI','Tạo bản nháp theo chủ đề, sau đó xem lại trước khi xuất bản.')}<div class="row g-4"><div class="col-lg-5"><div class="cardx card-pad">${section('Thiết lập câu hỏi','Mô tả nội dung bạn muốn tạo')}<form id="generator-form"><label class="form-label">Chủ đề</label><select class="form-select mb-3" required><option value="">Chọn chủ đề</option>${topicNames.map(t=>`<option>${t}</option>`).join('')}<option>Phương trình bậc hai</option></select><label class="form-label">Bài học</label><select class="form-select mb-3"><option>Hàm số bậc hai và đồ thị</option><option>Dấu của tam thức bậc hai</option></select><label class="form-label">Loại câu hỏi</label><div class="d-flex gap-2 mb-3"><label class="btn btn-soft flex-fill"><input type="radio" name="qtype" checked> Trắc nghiệm</label><label class="btn btn-light flex-fill"><input type="radio" name="qtype"> Tự luận</label></div><div class="row g-3"><div class="col-6"><label class="form-label">Độ khó</label><select class="form-select"><option>Cơ bản</option><option>Trung bình</option><option>Nâng cao</option></select></div><div class="col-6"><label class="form-label">Số câu</label><select class="form-select"><option>5 câu</option><option>10 câu</option><option>3 câu</option></select></div></div><label class="form-label mt-3">Ghi chú thêm <span class="muted fw-normal">(không bắt buộc)</span></label><textarea class="form-control" rows="3" placeholder="Ví dụ: tập trung vào cách xác định trục đối xứng..."></textarea><button class="btn btn-primary w-100 mt-3" type="submit">Tạo câu hỏi nháp</button><div class="tiny muted text-center mt-2">Câu hỏi AI tạo cần được giáo viên duyệt trước khi đăng.</div></form></div></div><div class="col-lg-7"><div class="cardx card-pad h-100" id="generator-results">${section('Bản nháp câu hỏi','Câu hỏi được tạo sẽ xuất hiện tại đây')}<div class="empty-state"><div style="font-size:35px">AI</div><strong class="d-block mt-2">Sẵn sàng tạo câu hỏi</strong><span class="tiny">Chọn chủ đề và thiết lập ở bên trái để bắt đầu.</span></div></div></div></div>`}
function adminDashboard(){return `${heading('Tổng quan hệ thống','Theo dõi hoạt động học tập và nội dung trên Math10 AI.',`<button class="btn btn-primary" data-modal="user">＋ Tạo tài khoản</button>`)}<div class="row g-3 mb-4">${metric('Tổng người dùng','486','32 giáo viên · 454 học sinh','users')}${metric('Bài học đã xuất bản','84','Trên 7 chủ đề Toán 10','book','green')}${metric('Câu hỏi trong hệ thống','1,248','96 câu tự luận','quiz','orange')}${metric('Lượt học tuần này','2,816','↑ 12% so với tuần trước','chart','purple')}</div><div class="row g-4"><div class="col-xl-8"><div class="cardx mb-4"><div class="card-pad pb-0">${section('Người dùng mới','Tài khoản vừa được tạo',`<a href="#users" data-page="users">Quản lý người dùng →</a>`)}</div><div class="table-responsive"><table class="table"><thead><tr><th>Người dùng</th><th>Vai trò</th><th>Ngày tạo</th><th>Trạng thái</th></tr></thead><tbody>${[['Nguyễn Hoàng Long','Học sinh','Hôm nay','Hoạt động','HL'],['Trần Thu Trang','Giáo viên','Hôm qua','Hoạt động','TT'],['Phạm Gia Hân','Học sinh','28/09/2026','Chờ kích hoạt','GH']].map((u,i)=>`<tr><td><div class="d-flex align-items-center gap-2">${avatar(u[4],['blue','purple','green'][i])}<div><strong>${u[0]}</strong><div class="tiny muted">${u[0].toLowerCase().replaceAll(' ','.')}@math10.edu.vn</div></div></div></td><td>${u[1]}</td><td>${u[2]}</td><td><span class="tag ${i===2?'tag-orange':'tag-green'}">${u[3]}</span></td></tr>`).join('')}</tbody></table></div></div><div class="cardx card-pad">${section('Hoạt động học tập','Số lượt luyện tập trong 7 ngày qua')}<div class="chart-area">${[44,68,35,83,57,90,70].map((v,i)=>`<div class="bar-group"><div class="bar alt" style="height:${v}%"></div><span class="bar-label">${['T2','T3','T4','T5','T6','T7','CN'][i]}</span></div>`).join('')}</div></div></div><div class="col-xl-4"><div class="cardx card-pad mb-4">${section('Tình trạng AI','Kết nối dịch vụ')}<div class="d-flex align-items-center justify-content-between p-3 rounded-3" style="background:#e7f7ef"><span><span class="legend-dot" style="background:#1b9668"></span><strong>AI Tutor</strong></span><span class="tag tag-green">Đang hoạt động</span></div><div class="d-flex justify-content-between mt-3 small"><span class="muted">Nhà cung cấp</span><strong>Gemini API</strong></div><div class="d-flex justify-content-between mt-2 small"><span class="muted">API key</span><strong>••••••••••••</strong></div><button class="btn btn-light w-100 mt-3" data-page="settings">Mở cấu hình AI</button></div><div class="cardx card-pad">${section('Quản lý nhanh')}<button class="btn btn-light w-100 text-start mb-2" data-page="users">♙ &nbsp;Tài khoản người dùng</button><button class="btn btn-light w-100 text-start mb-2" data-page="topics">▦ &nbsp;Chủ đề chương trình</button><button class="btn btn-light w-100 text-start" data-page="questions">◉ &nbsp;Ngân hàng câu hỏi</button></div></div></div>`}
function usersPage(){return `${heading('Quản lý người dùng','Tạo tài khoản, gán học sinh cho giáo viên và quản lý quyền.',`<button class="btn btn-primary" data-modal="user">＋ Tạo tài khoản</button>`)}<div class="row g-3 mb-3">${metric('Quản trị viên','2','Tài khoản hoạt động','settings')}${metric('Giáo viên','32','30 đang hoạt động','users','purple')}${metric('Học sinh','454','418 đang học','users','green')}${metric('Chờ kích hoạt','8','Cần kiểm tra','clock','orange')}</div><div class="cardx card-pad mb-3"><div class="filter-row"><input class="form-control" style="max-width:280px" placeholder="Tìm tên, email, username..."><select class="form-select" style="width:170px"><option>Tất cả vai trò</option><option>Admin</option><option>Giáo viên</option><option>Học sinh</option></select><select class="form-select" style="width:160px"><option>Mọi trạng thái</option><option>Hoạt động</option><option>Chờ kích hoạt</option></select></div></div><div class="cardx"><div class="table-responsive"><table class="table"><thead><tr><th>Người dùng</th><th>Vai trò</th><th>Giáo viên phụ trách</th><th>Trạng thái</th><th></th></tr></thead><tbody>${[['Nguyễn Hoàng Long','long.nguyen','Học sinh','Nguyễn Thu Hà','Hoạt động','HL'],['Trần Minh Khang','khang.tran','Học sinh','Nguyễn Thu Hà','Hoạt động','MK'],['Trần Thu Trang','trang.tran','Giáo viên','—','Hoạt động','TT'],['Lê Ngọc Bảo','bao.le','Học sinh','Đỗ Minh Tâm','Chờ kích hoạt','NB']].map((u,i)=>`<tr><td><div class="d-flex align-items-center gap-2">${avatar(u[5],['blue','green','purple','orange'][i])}<div><strong>${u[0]}</strong><div class="tiny muted">@${u[1]}</div></div></div></td><td><span class="tag ${u[2]==='Giáo viên'?'tag-purple':'tag-blue'}">${u[2]}</span></td><td>${u[3]}</td><td><span class="tag ${u[4]==='Hoạt động'?'tag-green':'tag-orange'}">${u[4]}</span></td><td><button class="btn btn-light btn-sm" data-modal="user">Chỉnh sửa</button></td></tr>`).join('')}</tbody></table></div></div>`}
function topicsPage(){return `${heading('Chủ đề Toán 10','Sắp xếp nội dung theo chương trình sách giáo khoa.',`<button class="btn btn-primary" data-modal="topic">＋ Thêm chủ đề</button>`)}<div class="alert alert-warning small"><strong>Chưa chọn bộ sách.</strong> Hãy xác nhận một chương trình Toán 10 trước khi chốt cấu trúc chủ đề và dữ liệu mẫu.</div><div class="row g-3">${topicNames.map((t,i)=>`<div class="col-md-6 col-xl-4"><div class="cardx card-pad h-100"><div class="d-flex align-items-start justify-content-between"><span class="tag tag-blue">CHỦ ĐỀ ${String(i+1).padStart(2,'0')}</span><button class="btn btn-light btn-sm">•••</button></div><h3 style="font-size:16px;margin:14px 0 5px">${t}</h3><p class="tiny muted">${[8,6,7,5,4,3][i]} bài giảng · ${[54,42,48,30,24,18][i]} câu hỏi</p><div class="progress mb-3"><div class="progress-bar" style="width:${[82,64,45,32,23,12][i]}%"></div></div><div class="d-flex justify-content-between tiny muted"><span>Tiến độ học sinh</span><strong>${[82,64,45,32,23,12][i]}%</strong></div><div class="border-top mt-3 pt-3 d-flex justify-content-between"><button class="btn btn-light btn-sm" data-page="lessons">Xem bài giảng</button><button class="btn btn-soft btn-sm" data-modal="topic">Chỉnh sửa</button></div></div></div>`).join('')}</div>`}
function settingsPage(){return `${heading('Cấu hình AI','Quản lý kết nối và cách AI hỗ trợ người học.')}<div class="row g-4"><div class="col-xl-7"><div class="cardx card-pad mb-4">${section('Nhà cung cấp AI','Thông tin kết nối được lưu ở phía máy chủ')}<label class="form-label">Nhà cung cấp</label><select class="form-select mb-3"><option>Gemini API</option><option>OpenAI API</option></select><label class="form-label">Model</label><input class="form-control mb-3" value="gemini-2.5-flash"><label class="form-label">API key</label><div class="input-group"><input type="password" class="form-control" placeholder="Chỉ nhập khi cần thay khóa" id="api-key"><button class="btn btn-light" id="toggle-key">Hiện</button></div><div class="tiny muted mt-2">Khóa được giữ bí mật ở máy chủ, không gửi xuống trình duyệt sau khi lưu.</div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary" data-action="save-settings">Lưu cấu hình</button><button class="btn btn-light" data-action="test-ai">Kiểm tra kết nối</button></div></div><div class="cardx card-pad">${section('Tính năng AI','Bật hoặc tắt theo nhu cầu hệ thống')}${[['Sinh câu hỏi cho giáo viên','Giáo viên tạo câu hỏi nháp bằng AI',true],['Gia sư từng bước','Gợi ý theo lượt khi học sinh trả lời sai',true],['Nhận xét ảnh tự luận','Đọc ảnh và chỉ ra bước cần sửa',true]].map(x=>`<div class="d-flex justify-content-between align-items-center py-3 border-top"><div><strong>${x[0]}</strong><div class="tiny muted mt-1">${x[1]}</div></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" checked role="switch" aria-label="${x[0]}"></div></div>`).join('')}</div></div><div class="col-xl-5"><div class="cardx card-pad">${section('Hành vi gia sư','Thiết lập cách AI hướng dẫn học sinh')}<label class="form-label">Số gợi ý tối đa trước khi hiện lời giải</label><select class="form-select"><option>3 gợi ý</option><option>2 gợi ý</option><option>4 gợi ý</option></select><div class="alert alert-primary small mt-3">AI đưa từng gợi ý, yêu cầu học sinh nhập bước tiếp theo và không tiết lộ ngay đáp án sau lần sai đầu tiên.</div><label class="form-label mt-2">Ngôn ngữ phản hồi</label><select class="form-select mb-3"><option>Tiếng Việt</option></select><label class="form-label">Mức kiến thức</label><select class="form-select"><option>Toán phổ thông — ưu tiên lớp 10</option></select><div class="border-top mt-4 pt-3"><div class="d-flex justify-content-between small"><span class="muted">Lần kiểm tra gần nhất</span><strong>Chưa kiểm tra</strong></div><div class="d-flex justify-content-between small mt-2"><span class="muted">Trạng thái dịch vụ</span><span class="tag tag-orange">Chưa kết nối</span></div></div></div></div></div>`}
function pageView(){if(state.role==='student'){return ({dashboard:dashboardStudent,lessons:lessonsStudent,'lesson-detail':lessonDetail,formulas:formulasPage,practice,essay:essayPage,'ai-tutor':aiTutorPage,history:historyPage,progress:progressPage}[state.page]||dashboardStudent)()}if(state.role==='teacher'){return ({dashboard:teacherDash,students:teacherStudents,lessons:teacherLessons,questions:questionsPage,generator:generatorPage,progress:progressPage}[state.page]||teacherDash)()}return ({dashboard:adminDashboard,users:usersPage,topics:topicsPage,lessons:teacherLessons,questions:questionsPage,settings:settingsPage}[state.page]||adminDashboard)()}
function toast(message,type='success'){const id='t'+Date.now();document.querySelector('#toast-container').insertAdjacentHTML('beforeend',`<div class="toast show mb-2" id="${id}" role="status"><div class="toast-header"><span class="legend-dot" style="background:${type==='success'?'#198460':'#e09224'}"></span><strong class="me-auto">Math10 AI</strong><button type="button" class="btn-close" data-bs-dismiss="toast"></button></div><div class="toast-body">${htmlSafe(message)}</div></div>`);setTimeout(()=>document.getElementById(id)?.remove(),3600)}
function modal(type){const config={lesson:['Tạo bài giảng mới','Tên bài giảng','Nhập tên bài giảng...'],student:['Thêm học sinh','Email học sinh','name@student.edu.vn'],user:['Tạo tài khoản','Họ và tên','Nhập họ tên...'],topic:['Thêm chủ đề','Tên chủ đề','Nhập tên chủ đề...'],question:['Tạo câu hỏi','Nội dung câu hỏi','Nhập nội dung câu hỏi...']}[type]||['Tạo mới','Tên',''];document.querySelector('#action-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal fade" id="action-modal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><div class="eyebrow">MATH10 AI</div><h5 class="modal-title fw-bold">${config[0]}</h5></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">${config[1]}</label><input class="form-control mb-3" placeholder="${config[2]}">${type==='student'?'<label class="form-label">Lớp</label><select class="form-select mb-3"><option>10A1</option><option>10A2</option></select>':''}${type==='user'?'<label class="form-label">Vai trò</label><select class="form-select mb-3"><option>Giáo viên</option><option>Học sinh</option></select>':''}<label class="form-label">Ghi chú <span class="muted fw-normal">(không bắt buộc)</span></label><textarea class="form-control" rows="2" placeholder="Mô tả ngắn..."></textarea></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Hủy</button><button class="btn btn-primary" id="save-modal">Lưu thông tin</button></div></div></div></div>`);const el=document.querySelector('#action-modal');bootstrap.Modal.getOrCreateInstance(el).show();el.querySelector('#save-modal').onclick=()=>{bootstrap.Modal.getInstance(el).hide();toast('Đã lưu thông tin thành công.')}}
function render(){const routeHash='#'+state.page;if(window.location.hash!==routeHash)history.pushState({page:state.page},'',window.location.pathname+window.location.search+routeHash);if(window.MathJax?.typesetClear)window.MathJax.typesetClear([app]);app.innerHTML=shell();const actions=app.querySelector('.top-actions');if(actions)actions.insertAdjacentHTML('afterbegin',state.sessionUser?`<span class="tiny muted">${htmlSafe(state.sessionUser.fullName)} · ${htmlSafe(state.sessionUser.role)}</span><button class="btn btn-light btn-sm" id="auth-logout">Đăng xuất</button>`:'<button class="btn btn-light btn-sm" id="auth-open">Đăng nhập</button><span class="tag tag-orange">Chế độ xem thử</span>');const roleSelect=app.querySelector('#role-select');if(state.sessionUser&&roleSelect){roleSelect.value=state.sessionUser.role.toLowerCase();roleSelect.disabled=true}if(state.sessionUser?.role==='ADMIN')app.querySelector('#question-generate-form')?.closest('.cardx')?.classList.add('d-none');app.querySelectorAll('[data-question-id]').forEach(card=>{if(!card.querySelector('[data-edit-question]'))card.insertAdjacentHTML('beforeend',`<button class="btn btn-light btn-sm mt-3 ms-2" data-edit-question="${card.dataset.questionId}">Chỉnh sửa</button>`)});if(window.MathJax?.typesetPromise)window.MathJax.typesetPromise([app]).catch(()=>{});document.title=`${pageName()} — Math10 AI`}
app.addEventListener('click',e=>{const target=e.target.closest('[data-page],[data-modal],[data-answer],[data-action],#menu-toggle,#search-toggle,#notification-btn,#submit-answer,#essay-submit,#toggle-key');if(!target)return;if(target.dataset.page){smoothPageTransition(()=>{state.page=target.dataset.page;state.selectedAnswer=null;render();window.scrollTo({top:0,behavior:'smooth'})});return}if(target.dataset.modal){modal(target.dataset.modal);return}if(target.id==='menu-toggle'){document.querySelector('#sidebar').classList.toggle('open');return}if(target.id==='search-toggle'){const box=app.querySelector('.searchbox');const open=!box?.classList.contains('mobile-open');box?.classList.toggle('mobile-open',open);target.setAttribute('aria-expanded',String(open));if(open)setTimeout(()=>app.querySelector('#global-search')?.focus(),0);return}if(target.id==='notification-btn'){toast('Bạn chưa có thông báo mới.');return}if(target.dataset.answer!==undefined){state.selectedAnswer=Number(target.dataset.answer);render();const fb=document.querySelector('#quiz-feedback');if(fb){fb.innerHTML=state.selectedAnswer===1?'<div class="alert alert-success py-3 px-3 rounded-3 mt-3"><div class="fw-bold mb-1">Chính xác!</div><div>Trục đối xứng có phương trình x = −b/(2a) = 1. Làm tốt lắm!</div></div><div class="d-flex justify-content-end mt-3"><button class="btn btn-primary" id="mock-next-q">Câu tiếp theo →</button></div>':'<div class="alert alert-danger py-3 px-3 rounded-3 mt-3"><div class="fw-bold mb-1">Chưa chính xác</div><div class="mb-2"><strong>Đáp án đúng:</strong> B — x = 1</div><div class="pt-2 border-top border-danger border-opacity-25"><strong>Giải thích:</strong> Trục đối xứng của parabol y = ax² + bx + c có phương trình x = −b/(2a). Ở đây a = 2, b = −4 nên x = −(−4)/(2·2) = 1.</div></div><div class="d-flex justify-content-end mt-3"><button class="btn btn-primary" id="mock-next-q">Câu tiếp theo →</button></div>'}return}if(target.id==='submit-answer'){const fb=document.querySelector('#quiz-feedback');if(state.selectedAnswer===null){toast('Chọn một đáp án trước khi kiểm tra.','warning');return}fb.innerHTML=state.selectedAnswer===1?'<div class="alert alert-success py-3 px-3 rounded-3 mt-3"><div class="fw-bold mb-1">Chính xác!</div><div>Trục đối xứng có phương trình x = −b/(2a) = 1. Làm tốt lắm!</div></div><div class="d-flex justify-content-end mt-3"><button class="btn btn-primary" id="mock-next-q">Câu tiếp theo →</button></div>':'<div class="alert alert-danger py-3 px-3 rounded-3 mt-3"><div class="fw-bold mb-1">Chưa chính xác</div><div class="mb-2"><strong>Đáp án đúng:</strong> B — x = 1</div><div class="pt-2 border-top border-danger border-opacity-25"><strong>Giải thích:</strong> Trục đối xứng của parabol y = ax² + bx + c có phương trình x = −b/(2a). Ở đây a = 2, b = −4 nên x = −(−4)/(2·2) = 1.</div></div><div class="d-flex justify-content-end mt-3"><button class="btn btn-primary" id="mock-next-q">Câu tiếp theo →</button></div>';return}if(target.id==='essay-submit'){if(!document.querySelector('#essay-upload')?.files.length){toast('Bạn hãy chọn ảnh lời giải trước nhé.','warning');return}toast('Đã nhận bài làm. Gia sư AI đang phân tích từng bước...');return}if(target.id==='toggle-key'){const input=document.querySelector('#api-key');input.type=input.type==='password'?'text':'password';target.textContent=input.type==='password'?'Hiện':'Ẩn';return}if(target.dataset.action==='approve'){target.outerHTML='<span class="tag tag-green">Đã duyệt</span>';toast('Câu hỏi đã được duyệt thành công.');return}if(target.dataset.action==='save-settings'){toast('Đã lưu cấu hình AI an toàn.');return}if(target.dataset.action==='test-ai'){toast('Kết nối AI hoạt động bình thường.');return}});
app.addEventListener('change',e=>{if(e.target.id==='role-select'){state.role=e.target.value;state.page='dashboard';render();return}if(e.target.id==='essay-upload'){const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){e.target.value='';toast('Ảnh vượt quá giới hạn 10 MB.','warning');return}document.querySelector('#upload-name').textContent=file.name;const img=document.querySelector('#upload-preview');img.src=URL.createObjectURL(file);img.classList.remove('d-none');document.querySelector('#upload-zone').style.minHeight='auto'}});
app.addEventListener('submit',e=>{if(e.target.id==='generator-form'){e.preventDefault();const box=document.querySelector('#generator-results');box.innerHTML=`${section('Bản nháp câu hỏi','5 câu · Hàm số bậc hai · Cơ bản')}<div class="alert alert-warning small">Đây là bản nháp do AI tạo. Hãy xem lại đáp án và lời giải trước khi lưu.</div>${['Đồ thị hàm số y = x² − 4x + 3 có trục đối xứng là?','Tọa độ đỉnh của parabol y = x² + 2x − 3 là?','Giá trị nhỏ nhất của hàm số y = x² − 6x + 10 bằng bao nhiêu?'].map((q,i)=>`<div class="border rounded-3 p-3 mb-2"><div class="d-flex justify-content-between"><strong class="small">${i+1}. ${q}</strong><span class="tag tag-orange">Chờ duyệt</span></div><div class="tiny muted mt-2">A. x = 2 &nbsp; B. x = −2 &nbsp; C. x = 1 &nbsp; D. x = 0</div><div class="d-flex gap-2 mt-3"><button class="btn btn-light btn-sm" data-action="approve">Duyệt câu này</button><button class="btn btn-soft btn-sm" data-action="approve">Chỉnh sửa</button></div></div>`).join('')}<button class="btn btn-primary w-100 mt-2" data-action="approve">Duyệt tất cả câu hỏi</button>`;toast('Đã tạo bản nháp. Hãy kiểm tra trước khi xuất bản.')}});
