const catalog={loaded:false,online:false,topics:[],lessons:[],error:''};
const fallbackLessons=[
 {id:1,topicId:1,title:'Mệnh đề và tập hợp',description:'Các khái niệm cơ bản về mệnh đề và tập hợp.',content:'KIẾN THỨC CỐT LÕI: Mệnh đề là câu khẳng định có giá trị đúng hoặc sai xác định. Câu hỏi, câu cảm thán và câu mệnh lệnh không phải mệnh đề. Câu chứa biến như x > 3 là mệnh đề chứa biến; cần cho giá trị của x hoặc thêm lượng từ để xác định đúng sai.\nPHỦ ĐỊNH: Phủ định của P kí hiệu ¬P, có giá trị chân lí ngược với P. Phủ định của mọi x có tính chất P là tồn tại x không có tính chất P; phủ định của tồn tại x có tính chất P là mọi x đều không có tính chất P.\nMỆNH ĐỀ KÉO THEO: P ⇒ Q chỉ sai khi P đúng và Q sai. P là điều kiện đủ để có Q; Q là điều kiện cần của P. P ⇔ Q đúng khi P và Q cùng giá trị chân lí.\nVÍ DỤ CÓ HƯỚNG DẪN: 12 chia hết cho 3 là mệnh đề đúng; phủ định 12 không chia hết cho 3 là mệnh đề sai. Nếu P là n chia hết cho 4 và Q là n chẵn thì P ⇒ Q đúng, nhưng chiều ngược lại không đúng với mọi n.\nTỰ KIỂM TRA: x² ≥ 0 với mọi số thực x là mệnh đề đúng. x² = 1 chưa có giá trị đúng sai nếu chưa chỉ rõ x hoặc lượng từ.\nGHI NHỚ: Khi phủ định câu có lượng từ, đổi mọi thành tồn tại và tồn tại thành mọi; đồng thời phủ định tính chất đi kèm.',videoUrl:null,resourceUrl:null,order:1,topicName:'Mệnh đề và tập hợp'},
 {id:2,topicId:1,title:'Các phép toán trên tập hợp',description:'Hợp, giao và hiệu của hai tập hợp.',content:'Tìm hiểu các phép toán cơ bản trên tập hợp.',videoUrl:null,resourceUrl:null,order:2,topicName:'Mệnh đề và tập hợp'},
 {id:3,topicId:2,title:'Bất phương trình bậc nhất',description:'Giải và biểu diễn tập nghiệm bất phương trình.',content:'Các bước giải bất phương trình bậc nhất một ẩn.',videoUrl:null,resourceUrl:null,order:1,topicName:'Bất phương trình'},
 {id:4,topicId:3,title:'Giải tam giác',description:'Vận dụng định lý sin và định lý cosin.',content:'Sử dụng các hệ thức lượng để giải tam giác.',videoUrl:null,resourceUrl:null,order:1,topicName:'Hệ thức lượng trong tam giác'},
 {id:5,topicId:4,title:'Khái niệm vectơ',description:'Nhận biết vectơ và các phép toán vectơ.',content:'Vectơ được xác định bởi hướng và độ dài.',videoUrl:null,resourceUrl:null,order:1,topicName:'Vectơ'},
 {id:6,topicId:5,title:'Hàm số bậc hai và đồ thị',description:'Khảo sát dạng đồ thị parabol.',content:'Hàm số bậc hai có dạng y = ax² + bx + c, với a khác 0.',videoUrl:null,resourceUrl:null,order:1,topicName:'Hàm số bậc hai'}
];
const apiBase=(window.MATH10_API_BASE_URL||'http://localhost:8080/api/v1').replace(/\/$/,'');
const htmlSafe=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function tutorMessageHtml(value){const lines=htmlSafe(value).split(/\r?\n/);let html='',list='';const closeList=()=>{if(list){html+=`</${list}>`;list=''}};const inline=line=>line.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');for(const line of lines){const match=line.match(/^\s*(?:([-*])|(\d+)\.)\s+(.+)$/);if(match){const kind=match[2]?'ol':'ul';if(list!==kind){closeList();list=kind;html+=`<${list} class="tutor-answer-list">`}html+=`<li>${inline(match[3])}</li>`}else{closeList();html+=line.trim()?`${inline(line)}<br>`:'<br>'}}closeList();return html.replace(/(?:<br>){3,}/g,'<br><br>')}
async function loadCatalog(){
 try{
  const [topicResponse,lessonResponse]=await Promise.all([fetch(`${apiBase}/topics`,{credentials:'include'}),fetch(`${apiBase}/lessons`,{credentials:'include'})]);
  if(!topicResponse.ok||!lessonResponse.ok)throw new Error(`API trả về HTTP ${!topicResponse.ok?topicResponse.status:lessonResponse.status}`);
  const [topics,lessons]=await Promise.all([topicResponse.json(),lessonResponse.json()]);
  if(!Array.isArray(topics)||!Array.isArray(lessons))throw new Error('Dữ liệu API không đúng định dạng.');
  catalog.topics=topics;catalog.lessons=lessons.map(lesson=>({...lesson,topicName:topics.find(topic=>topic.id===lesson.topicId)?.name||'Chủ đề'}));
  catalog.online=true;catalog.error='';
 }catch(error){catalog.online=false;catalog.error=error.message||'Không kết nối được API.'}
 catalog.loaded=true;
 if(state.page==='lessons'||state.page==='lesson-detail'||state.page==='topics'||(state.role==='student'&&state.page==='dashboard'))render();
}
function catalogNotice(){return `<div class="alert ${catalog.online?'alert-success':'alert-warning'} py-2 small" role="status">${catalog.online?'Nội dung đã tải trực tiếp từ SQL Server.':catalog.loaded?`Chưa kết nối được backend (${htmlSafe(catalog.error)}). Đang hiển thị dữ liệu mẫu.`:'Đang kết nối backend; tạm hiển thị dữ liệu mẫu.'}</div>`}
function catalogLessons(){return catalog.online?catalog.lessons:fallbackLessons}
function lessonsStudent(){
 const lessons=catalogLessons();
 const topics=catalog.online?catalog.topics.map(topic=>topic.name):[...new Set(fallbackLessons.map(lesson=>lesson.topicName))];
 const topicButtons=topics.map(name=>`<button class="btn btn-light topic-filter" data-topic="${htmlSafe(name)}">${htmlSafe(name)}</button>`).join('');
 const cards=lessons.map((lesson,index)=>{const cover=['cover-blue','cover-mint','cover-lilac','cover-amber'][index%4];const art=['∑','A ∩ B','→AB','y = ax²'][index%4];return `<div class="col-sm-6 col-xl-4 lesson-item" data-topic-name="${htmlSafe(lesson.topicName)}"><article class="cardx lesson-card"><div class="lesson-cover ${cover}"><span class="cover-tag">${htmlSafe(lesson.topicName.toUpperCase())}</span><span class="math-art">${art}</span></div><div class="lesson-body"><div class="lesson-meta"><span>Bài giảng</span><span>Toán 10</span></div><h3>${htmlSafe(lesson.title)}</h3><p class="tiny muted">${htmlSafe(lesson.description||'')}</p><button class="btn btn-soft w-100 mt-2" data-page="lesson-detail" data-lesson-id="${lesson.id}">Mở bài học →</button></div></article></div>`}).join('');
 return `${heading('Khám phá bài học','Chọn chủ đề và học theo nhịp độ của bạn.',`<button class="btn btn-primary" data-page="practice">◉ Luyện tập ngay</button>`)}${catalogNotice()}<div class="cardx card-pad mb-4"><div class="filter-row"><button class="btn btn-soft topic-filter active" data-topic="all">Tất cả chủ đề</button>${topicButtons}</div></div><div class="row g-3">${cards||'<div class="col-12"><div class="cardx card-pad muted">Chưa có bài học đã xuất bản trong cơ sở dữ liệu.</div></div>'}</div>`;
}
function renderLessonContent(raw,title=''){
 const labels={'KIẾN THỨC':'Kiến thức trọng tâm','KIẾN THỨC CỐT LÕI':'Kiến thức trọng tâm','CÔNG THỨC':'Công thức cần nhớ','PHỦ ĐỊNH':'Phủ định mệnh đề','MỆNH ĐỀ KÉO THEO':'Mệnh đề kéo theo','VÍ DỤ':'Ví dụ minh họa','VÍ DỤ CÓ HƯỚNG DẪN':'Ví dụ có hướng dẫn','GHI NHỚ':'Ghi nhớ','TỰ KIỂM TRA':'Tự kiểm tra'};
 const entries=String(raw||'Giáo viên chưa bổ sung nội dung cho bài học này.').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);
 const sections=[];
 for(const entry of entries){const match=entry.match(/^([^:]{2,48}):\s*(.*)$/);const label=match?.[1]?.trim().toLocaleUpperCase('vi');sections.push({title:labels[label]||null,text:match?match[2]:entry});}
 if(/mệnh đề/i.test(title)&&!entries.join(' ').includes('MỆNH ĐỀ KÉO THEO'))sections.push({title:'Mở rộng: lượng từ và kéo theo',text:'Với mệnh đề chứa biến P(x), lượng từ “mọi” viết ∀x và lượng từ “tồn tại” viết ∃x. Ví dụ: ∀x∈ℝ, x²≥0 là mệnh đề đúng. Phủ định của mệnh đề này là ∃x∈ℝ sao cho x²<0, mệnh đề sai. Với P: “n chia hết cho 4” và Q: “n chẵn”, P⇒Q đúng; chiều ngược Q⇒P không đúng với mọi số nguyên (chẳng hạn n=2).'});
 return sections.map(section=>'<section class="lesson-note">'+(section.title?'<h3>'+htmlSafe(section.title)+'</h3>':'')+'<p>'+htmlSafe(section.text).replace(/\n/g,'<br>')+'</p></section>').join('');
}
function lessonDetail(){
 const lesson=catalogLessons().find(item=>item.id===state.selectedLessonId)||catalogLessons()[0];
 if(!lesson)return `${heading('Chi tiết bài học','Chưa có bài học để hiển thị.')}${catalogNotice()}<button class="btn btn-light" data-page="lessons">← Danh sách bài học</button>`;
 const content=renderLessonContent(lesson.content||lesson.description,lesson.title);
 const externalUrl=value=>{try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}};
 const video=externalUrl(lesson.videoUrl);const resource=externalUrl(lesson.resourceUrl);
 return `<div class="mb-3"><button class="btn btn-light" data-page="lessons">← Tất cả bài học</button></div>${heading(htmlSafe(lesson.title),htmlSafe(`${lesson.topicName} · Bài học`))}${catalogNotice()}<div class="row g-4"><div class="col-xl-8"><article class="cardx card-pad"><span class="tag tag-blue">BÀI GIẢNG</span><h2 class="mt-3 mb-2 lesson-detail-title">${htmlSafe(lesson.title)}</h2><p class="muted">${htmlSafe(lesson.description||'')}</p><div class="lesson-content">${content}</div>${resource?`<a class="btn btn-light mt-3" href="${htmlSafe(resource)}" target="_blank" rel="noopener noreferrer">Mở tài liệu tham khảo ↗</a>`:''}${video?`<div class="mt-4"><span class="tag tag-orange">VIDEO BÀI GIẢNG</span><div class="mt-2"><a href="${htmlSafe(video)}" target="_blank" rel="noopener noreferrer">Mở video ↗</a></div></div>`:''}<hr><div class="d-flex flex-wrap gap-2"><button class="btn btn-primary" data-page="practice">Luyện tập trắc nghiệm →</button><button class="btn btn-soft" data-page="essay">Luyện tập tự luận →</button></div></article></div><div class="col-xl-4"><div class="cardx card-pad">${section('Thông tin bài học')}<div class="step-line"><div class="step-dot">1</div><div class="step-copy"><strong>${htmlSafe(lesson.title)}</strong><div>${htmlSafe(lesson.topicName)}</div></div></div><button class="btn btn-light w-100" data-page="lessons">Quay lại danh sách</button></div></div></div>`;
}
app.addEventListener('click',e=>{const lessonButton=e.target.closest('[data-lesson-id]');if(lessonButton)state.selectedLessonId=Number(lessonButton.dataset.lessonId)},{capture:true});
app.addEventListener('click',e=>{const filter=e.target.closest('.topic-filter');if(!filter)return;const value=filter.dataset.topic;setTimeout(()=>{document.querySelectorAll('.lesson-item').forEach(item=>item.classList.toggle('d-none',value!=='all'&&item.dataset.topicName!==value))},0)});
function apiFetch(path,options={}){const headers=new Headers(options.headers||{});if(state.sessionUser?.username)headers.set('X-Auth-User',state.sessionUser.username);if(options.body&&!headers.has('Content-Type')&&!(options.body instanceof FormData))headers.set('Content-Type','application/json');return fetch(`${apiBase}${path}`,{...options,headers,credentials:'include'}).then(async response=>{let data=null;try{data=await response.json()}catch{}if(!response.ok)throw new Error(data?.detail||`Yêu cầu thất bại (${response.status}).`);return data})}
function completeAuthentication(user){
 const requestedPage=state.page;
 state.sessionUser=user; state.role=user.role.toLowerCase(); state.selectedAnswer=null;
 try{localStorage.setItem('math10_session_user',JSON.stringify(user))}catch{}
 const studentPage=user.role==='STUDENT'&&['essay','practice','history','progress','lessons','lesson-detail','formulas','ai-tutor'].includes(requestedPage);
 state.page=studentPage?requestedPage:'dashboard';
 document.querySelector('#auth-dialog')?.remove(); render(); loadCatalog();
 if(state.page==='essay')loadEssaySet(); else if(state.page==='practice')startPractice(); else if(state.page==='history')loadHistory(); else if(state.page==='progress')loadProgress(); else if(state.page==='dashboard')loadDashboard();
}
function openLogin(initialRole='student'){
 document.querySelector('#auth-dialog')?.remove();
 document.body.insertAdjacentHTML('beforeend',`<div class="auth-overlay" id="auth-dialog"><div class="cardx card-pad auth-card" style="width:min(100%,440px)"><div class="d-flex justify-content-between align-items-start"><div><div class="eyebrow">MATH10 AI</div><h2 class="card-title" id="m-login-title" style="font-size:21px">Đăng nhập tài khoản</h2><p class="small muted mt-2" id="m-login-sub">Chọn vai trò của bạn để đăng nhập.</p></div><button class="btn-close" id="auth-close" aria-label="Đóng"></button></div><div class="d-flex gap-2 my-3 p-1 rounded-3" style="background:#eef2f8"><button class="btn btn-sm flex-fill fw-bold ${initialRole==='student'?'btn-primary':'btn-light'}" id="btn-tab-student" type="button">Học sinh</button><button class="btn btn-sm flex-fill fw-bold ${initialRole==='teacher'?'btn-primary':'btn-light'}" id="btn-tab-teacher" type="button">Giáo viên</button></div><form id="auth-form"><label class="form-label" id="m-user-label">Tên đăng nhập ${initialRole==='teacher'?'Giáo viên':'Học sinh'}</label><input class="form-control" name="username" id="m-login-username" required autocomplete="username" placeholder="${initialRole==='teacher'?'Ví dụ: teacher':'Ví dụ: student'}"><label class="form-label mt-3">Mật khẩu</label><input class="form-control" type="password" name="password" required autocomplete="current-password" placeholder="Nhập mật khẩu"><div class="small text-danger mt-3" id="auth-error"></div><button class="btn btn-primary w-100 mt-3" type="submit" id="m-login-submit">Đăng nhập ${initialRole==='teacher'?'Giáo viên':'Học sinh'} →</button></form><p class="small text-center mt-3 mb-0">Chưa có tài khoản? <button class="btn btn-link p-0" id="auth-to-register" type="button">Đăng ký ${initialRole==='teacher'?'Giáo viên':'Học sinh'}</button></p></div></div>`);
 let currentTabRole = initialRole;
 const setTab = (r) => {
   currentTabRole = r;
   const btnS = document.querySelector('#btn-tab-student');
   const btnT = document.querySelector('#btn-tab-teacher');
   const uLabel = document.querySelector('#m-user-label');
   const uInput = document.querySelector('#m-login-username');
   const submitBtn = document.querySelector('#m-login-submit');
   const toReg = document.querySelector('#auth-to-register');
   if(r === 'teacher'){
     btnT.className = 'btn btn-sm flex-fill fw-bold btn-primary';
     btnS.className = 'btn btn-sm flex-fill fw-bold btn-light';
     uLabel.textContent = 'Tên đăng nhập Giáo viên';
     uInput.placeholder = 'Ví dụ: teacher';
     submitBtn.textContent = 'Đăng nhập Giáo viên →';
     toReg.textContent = 'Đăng ký Giáo viên';
   } else {
     btnS.className = 'btn btn-sm flex-fill fw-bold btn-primary';
     btnT.className = 'btn btn-sm flex-fill fw-bold btn-light';
     uLabel.textContent = 'Tên đăng nhập Học sinh';
     uInput.placeholder = 'Ví dụ: student';
     submitBtn.textContent = 'Đăng nhập Học sinh →';
     toReg.textContent = 'Đăng ký học sinh';
   }
 };
 document.querySelector('#btn-tab-student').onclick = () => setTab('student');
 document.querySelector('#btn-tab-teacher').onclick = () => setTab('teacher');
 document.querySelector('#auth-close').onclick=()=>document.querySelector('#auth-dialog')?.remove();
 document.querySelector('#auth-to-register').onclick=()=>openRegister(currentTabRole);
 document.querySelector('#auth-dialog').addEventListener('click',e=>{if(e.target.id==='auth-dialog')e.currentTarget.remove()});
 document.querySelector('#auth-form').addEventListener('submit',async e=>{
  e.preventDefault(); const form=new FormData(e.currentTarget); const button=e.currentTarget.querySelector('[type=submit]'); button.disabled=true;
  try{const user=await apiFetch('/auth/login',{method:'POST',body:JSON.stringify({username:form.get('username'),password:form.get('password')})});completeAuthentication(user)}
  catch(error){document.querySelector('#auth-error').textContent=error.message;button.disabled=false}
 });
}
function openRegister(initialRole='student'){
 document.querySelector('#auth-dialog')?.remove();
 const isTeacher = initialRole === 'teacher';
 document.body.insertAdjacentHTML('beforeend',`<div class="auth-overlay" id="auth-dialog"><div class="cardx card-pad auth-card" style="width:min(100%,460px)"><div class="d-flex justify-content-between align-items-start"><div><div class="eyebrow" id="reg-m-eyebrow">MATH10 AI — ĐĂNG KÝ ${isTeacher?'GIÁO VIÊN':'HỌC SINH'}</div><h2 class="card-title" id="reg-m-title" style="font-size:21px">Tạo tài khoản ${isTeacher?'Giáo viên':'Học sinh'}</h2><p class="small muted mt-2" id="reg-m-sub">${isTeacher?'Đăng ký để quản lý lớp học và tạo đề thi AI.':'Đăng ký để lưu bài làm và theo dõi tiến độ học tập.'}</p></div><button class="btn-close" id="register-close" aria-label="Đóng"></button></div><div class="d-flex gap-2 my-2 p-1 rounded-3" style="background:#eef2f8"><button class="btn btn-sm flex-fill fw-bold ${!isTeacher?'btn-primary':'btn-light'}" id="reg-tab-s" type="button">Học sinh</button><button class="btn btn-sm flex-fill fw-bold ${isTeacher?'btn-primary':'btn-light'}" id="reg-tab-t" type="button">Giáo viên</button></div><form id="register-form"><label class="form-label mt-2" id="reg-label-name">Họ và tên ${isTeacher?'Giáo viên':'học sinh'}</label><input class="form-control" name="fullName" required maxlength="120" autocomplete="name" placeholder="${isTeacher?'Thầy/Cô Nguyễn Văn A':'Nguyễn Văn A'}"><label class="form-label mt-3">Tên đăng nhập</label><input class="form-control" name="username" required maxlength="50" autocomplete="username" placeholder="${isTeacher?'teacher_toan10':'hocsinh10'}"><label class="form-label mt-3">Email</label><input class="form-control" type="email" name="email" required maxlength="254" autocomplete="email"><label class="form-label mt-3">Mật khẩu</label><input class="form-control" type="password" name="password" required minlength="12" maxlength="200" autocomplete="new-password"><label class="form-label mt-3">Nhập lại mật khẩu</label><input class="form-control" type="password" name="confirmPassword" required minlength="12" maxlength="200" autocomplete="new-password"><div class="tiny muted mt-2">Mật khẩu cần có ít nhất 12 ký tự.</div><div class="small text-danger mt-3" id="register-error"></div><button class="btn btn-primary w-100 mt-3" type="submit" id="reg-submit-btn">Tạo tài khoản ${isTeacher?'Giáo viên':'Học sinh'} và tiếp tục</button></form><p class="small text-center mt-3 mb-0">Đã có tài khoản? <button class="btn btn-link p-0" id="register-to-login" type="button">Đăng nhập</button></p></div></div>`);
 let selectedRole = isTeacher ? 'TEACHER' : 'STUDENT';
 const setRegTab = (r) => {
   selectedRole = r;
   const btnS = document.querySelector('#reg-tab-s');
   const btnT = document.querySelector('#reg-tab-t');
   const eb = document.querySelector('#reg-m-eyebrow');
   const tt = document.querySelector('#reg-m-title');
   const sb = document.querySelector('#reg-m-sub');
   const lbl = document.querySelector('#reg-label-name');
   const btn = document.querySelector('#reg-submit-btn');
   if(r === 'TEACHER'){
     btnT.className = 'btn btn-sm flex-fill fw-bold btn-primary';
     btnS.className = 'btn btn-sm flex-fill fw-bold btn-light';
     eb.textContent = 'MATH10 AI — ĐĂNG KÝ GIÁO VIÊN';
     tt.textContent = 'Tạo tài khoản Giáo viên';
     sb.textContent = 'Đăng ký để quản lý lớp học và tạo đề thi AI.';
     lbl.textContent = 'Họ và tên Giáo viên';
     btn.textContent = 'Tạo tài khoản Giáo viên và tiếp tục';
   } else {
     btnS.className = 'btn btn-sm flex-fill fw-bold btn-primary';
     btnT.className = 'btn btn-sm flex-fill fw-bold btn-light';
     eb.textContent = 'MATH10 AI — ĐĂNG KÝ HỌC SINH';
     tt.textContent = 'Tạo tài khoản Học sinh';
     sb.textContent = 'Đăng ký để lưu bài làm và theo dõi tiến độ học tập.';
     lbl.textContent = 'Họ và tên học sinh';
     btn.textContent = 'Tạo tài khoản Học sinh và tiếp tục';
   }
 };
 document.querySelector('#reg-tab-s').onclick = () => setRegTab('STUDENT');
 document.querySelector('#reg-tab-t').onclick = () => setRegTab('TEACHER');
 document.querySelector('#register-close').onclick=()=>document.querySelector('#auth-dialog')?.remove();
 document.querySelector('#register-to-login').onclick=()=>openLogin(selectedRole==='TEACHER'?'teacher':'student');
 document.querySelector('#auth-dialog').addEventListener('click',e=>{if(e.target.id==='auth-dialog')e.currentTarget.remove()});
 document.querySelector('#register-form').addEventListener('submit',async e=>{
  e.preventDefault(); const form=e.currentTarget; const values=Object.fromEntries(new FormData(form)); const error=document.querySelector('#register-error');
  if(values.password!==values.confirmPassword){error.textContent='Mật khẩu nhập lại chưa khớp.';return}
  const button=form.querySelector('[type=submit]');button.disabled=true;delete values.confirmPassword;
  values.role = selectedRole;
  try{const user=await apiFetch('/auth/register',{method:'POST',body:JSON.stringify(values)});completeAuthentication(user);toast(`Tạo tài khoản ${selectedRole==='TEACHER'?'Giáo viên':'Học sinh'} thành công. Chào mừng bạn!`)}
  catch(problem){error.textContent=problem.message;button.disabled=false}
 });
}
async function restoreSession(){try{const saved=localStorage.getItem('math10_session_user');if(saved){state.sessionUser=JSON.parse(saved);state.role=state.sessionUser.role.toLowerCase();render();loadPageData(state.page)}}catch{}try{const live=await apiFetch('/auth/me');state.sessionUser=live;state.role=live.role.toLowerCase();try{localStorage.setItem('math10_session_user',JSON.stringify(live))}catch{}if(!pageAllowed(state.role,state.page))state.page='dashboard';render();loadPageData(state.page)}catch{const saved=localStorage.getItem('math10_session_user');if(!saved){state.sessionUser=null;if(!pageAllowed(state.role,state.page)){state.page='dashboard';render()}}}}
app.addEventListener('click',async e=>{if(e.target.closest('#auth-open')){openLogin();return}if(e.target.closest('#auth-logout')){try{await apiFetch('/auth/logout',{method:'POST'})}catch{}try{localStorage.removeItem('math10_session_user')}catch{}state.sessionUser=null;state.role='student';state.page='dashboard';render();return}},{capture:true});
let practiceQuestions=[],practiceIndex=0,practiceLoading=false,practiceSubmitting=false,practiceError='',practiceAttempt=null,practiceTutor=null,historyData=[],historyLoading=false;
function practice(){
 if(!state.sessionUser)return `${heading('Luyện tập trắc nghiệm','Đăng nhập để lưu kết quả và xem nhận xét sau mỗi câu.')}<div class="cardx card-pad text-center"><button class="btn btn-primary" id="auth-open">Đăng nhập để bắt đầu</button></div>`;
 if(practiceLoading)return `${heading('Luyện tập trắc nghiệm','Đang tải câu hỏi từ ngân hàng câu hỏi...')}<div class="cardx card-pad">Đang tải câu hỏi…</div>`;
 if(practiceError)return `${heading('Luyện tập trắc nghiệm','Không tải được câu hỏi.')}<div class="alert alert-warning">${htmlSafe(practiceError)}</div><button class="btn btn-light" data-page="lessons">Quay lại bài học</button>`;
 if(!practiceQuestions.length)return `${heading('Luyện tập trắc nghiệm','Bài học này chưa có câu trắc nghiệm đã xuất bản.')}<div class="cardx card-pad">Giáo viên cần tạo và xuất bản câu hỏi cho bài học này.</div><button class="btn btn-light mt-3" data-page="lessons">← Danh sách bài học</button>`;
 const q=practiceQuestions[practiceIndex];
 if(!q)return `${heading('Hoàn thành luyện tập','Bạn đã làm xong bộ câu hỏi.')}<div class="cardx card-pad"><button class="btn btn-primary" data-page="history">Xem lịch sử kết quả</button></div>`;
 const options=[q.optionA,q.optionB,q.optionC,q.optionD],correctIndex='ABCD'.indexOf(practiceAttempt?.correctAnswer||'');
 const answers=options.map((value,index)=>{const selected=state.selectedAnswer===index;const isCorrect=Boolean(practiceAttempt)&&index===correctIndex;const isWrong=Boolean(practiceAttempt)&&selected&&!practiceAttempt.correct;const classes=['answer-option',selected?'selected':'',isCorrect?'is-correct':'',isWrong?'is-wrong':'',practiceSubmitting?'is-pending':''].filter(Boolean).join(' ');return `<div class="${classes}" data-answer="${index}" aria-disabled="${practiceSubmitting||Boolean(practiceAttempt)}"><span class="answer-letter">${'ABCD'[index]}</span><span class="answer-text">${htmlSafe(value)}</span>${isCorrect?'<span class="answer-result">Đáp án đúng</span>':''}${isWrong?'<span class="answer-result">Bạn chọn</span>':''}</div>`}).join('');
 const solution=practiceAttempt?.explanation||practiceAttempt?.solutionSteps;
 const result=practiceAttempt?practiceAttempt.correct?`<div class="quiz-result quiz-result-correct" role="status"><div class="fw-bold mb-1">Chính xác!</div>${solution?`<p class="mt-2 mb-0">${htmlSafe(solution)}</p>`:''}</div>`:`<div class="quiz-result quiz-result-wrong" role="status"><div class="fw-bold mb-1">Chưa chính xác</div><div class="correct-answer-line mb-2"><strong>Đáp án đúng:</strong> ${htmlSafe(practiceAttempt.correctAnswer||'—')}${correctIndex>=0?` — ${htmlSafe(options[correctIndex])}`:''}</div><div class="pt-2 border-top border-danger border-opacity-25"><strong>Giải thích:</strong> ${htmlSafe(solution||'Trục đối xứng của parabol y = ax² + bx + c có phương trình x = −b/(2a).')}</div></div>`:'';
 return `${heading('Luyện tập trắc nghiệm',`${htmlSafe(q.difficulty)} · Câu ${practiceIndex+1}/${practiceQuestions.length}`,`<button class="btn btn-light" data-page="lessons">Thoát</button>`)}<div class="row justify-content-center"><div class="col-xl-8"><div class="cardx card-pad"><div class="d-flex justify-content-between"><span class="tag tag-blue">TOÁN 10</span><span class="question-number">CÂU ${practiceIndex+1} / ${practiceQuestions.length}</span></div><div class="question-box"><div class="tiny muted mb-2">${practiceAttempt?'Kết quả câu trả lời':'Chọn một đáp án · Kết quả hiện ngay sau khi chọn'}</div><h2>${htmlSafe(q.text)}</h2><div class="mt-4">${answers}</div></div>${practiceSubmitting?'<div class="quiz-submit-status" role="status">Đang chấm câu trả lời…</div>':''}${result}${practiceAttempt?`<button class="btn btn-primary mt-3" id="next-question">${practiceIndex+1<practiceQuestions.length?'Câu tiếp theo →':'Hoàn tất luyện tập'}</button>`:'<div class="d-flex justify-content-between border-top pt-3"><button class="btn btn-light" data-page="lessons">Thoát</button><span class="tiny muted align-self-center">Chọn phương án để gửi câu trả lời</span></div>'}</div></div></div>`;
}
function historyPage(){if(!state.sessionUser)return `${heading('Lịch sử học','Đăng nhập để xem kết quả đã lưu.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;return `${heading('Lịch sử học','Các bài làm đã được lưu vào tài khoản của bạn.')}${historyLoading?'<div class="cardx card-pad">Đang tải lịch sử…</div>':`<div class="cardx"><div class="table-responsive"><table class="table"><thead><tr><th>Câu hỏi</th><th>Câu trả lời</th><th>Kết quả</th><th>Điểm</th><th>Thời gian</th></tr></thead><tbody>${historyData.map(a=>`<tr><td>${htmlSafe(a.questionText)}</td><td>${htmlSafe(a.answerText||'—')}</td><td>${a.correct===null?'Đã nhận':a.correct?'Đúng':'Sai'}</td><td>${a.score??'—'}</td><td>${htmlSafe(new Date(a.submittedAt).toLocaleString('vi-VN'))}</td></tr>`).join('')||'<tr><td colspan="5" class="text-center muted">Chưa có bài làm nào.</td></tr>'}</tbody></table></div></div>`}`}
let essayQuestions=[],essayLoading=false,essayError='',essayResult=null;
function essayPage(){if(!state.sessionUser)return `${heading('Luyện tập tự luận','Đăng nhập để nộp bài và lưu nhận xét AI.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;const q=essayQuestions[0];if(essayLoading)return `${heading('Luyện tập tự luận','Đang tải câu hỏi...')}<div class="cardx card-pad">Đang tải câu hỏi…</div>`;if(essayError||!q)return `${heading('Luyện tập tự luận','Nộp lời giải bằng chữ hoặc ảnh để nhận góp ý từng bước.')}${essayError?`<div class="alert alert-warning">${htmlSafe(essayError)}</div>`:'<div class="cardx card-pad">Chưa có câu tự luận đã xuất bản cho bài học này.</div>'}<button class="btn btn-light mt-3" data-page="lessons">← Bài học</button>`;return `${heading('Luyện tập tự luận','Nộp lời giải bằng chữ hoặc ảnh để nhận góp ý từng bước.')}<div class="row g-4"><div class="col-xl-7"><div class="cardx card-pad"><span class="tag tag-purple">TỰ LUẬN · ${htmlSafe(q.difficulty)}</span><h2 class="mt-3" style="font-size:19px">${htmlSafe(q.text)}</h2>${essayResult?`<div class="alert alert-primary mt-3"><strong>Nhận xét từ gia sư</strong><div class="mt-2">${htmlSafe(essayResult.feedback||'Đã lưu bài làm.')}</div></div><button class="btn btn-light" id="essay-reset">Làm lại</button>`:`<label class="form-label mt-3" for="essay-text">Các bước giải (có thể để trống nếu nộp ảnh)</label><textarea class="form-control" id="essay-text" rows="5" placeholder="Trình bày các bước giải của bạn..."></textarea><label for="essay-upload" class="upload-zone mt-3"><div><div class="upload-icon">↑</div><strong>Chọn ảnh lời giải</strong><div class="tiny muted mt-1">JPG, PNG, WEBP · tối đa 10 MB</div><div class="tiny text-primary mt-2" id="upload-name"></div><img id="upload-preview" alt="Xem trước bài làm" class="img-fluid rounded mt-2 d-none" style="max-height:180px"></div></label><input type="file" id="essay-upload" accept="image/jpeg,image/png,image/webp" class="d-none"><button class="btn btn-primary w-100 mt-3" id="essay-submit">Gửi bài cho AI nhận xét →</button>`}</div></div><div class="col-xl-5"><div class="cardx card-pad">${section('AI sẽ nhận xét gì?')}<div class="step-line"><div class="step-dot">1</div><div class="step-copy"><strong>Tìm bước đầu tiên cần xem lại</strong><div>AI đọc lời giải và đưa gợi ý để bạn tự tiếp tục.</div></div></div><div class="alert alert-primary small">Bài làm được lưu riêng tư. Hình ảnh không được cung cấp qua đường dẫn công khai.</div></div></div></div>`}
async function loadEssaySet(){if(!state.sessionUser)return;const lesson=state.selectedLessonId||catalogLessons().find(x=>x.id)?.id;if(!lesson){essayError='Chưa chọn được bài học.';render();return}essayLoading=true;essayError='';essayResult=null;render();try{essayQuestions=(await apiFetch(`/lessons/${lesson}/questions`)).filter(q=>q.type==='ESSAY')}catch(error){essayError=error.message;essayQuestions=[]}finally{essayLoading=false;render()}}
async function submitEssayReal(){const q=essayQuestions[0],text=document.querySelector('#essay-text')?.value?.trim()||'',file=document.querySelector('#essay-upload')?.files?.[0];if(!text&&!file){toast('Nhập lời giải hoặc chọn ảnh bài làm.','warning');return}if(file&&file.size>10*1024*1024){toast('Ảnh vượt quá giới hạn 10 MB.','warning');return}const data=new FormData();data.append('questionId',q.id);data.append('answerText',text);if(file)data.append('image',file);const button=document.querySelector('#essay-submit');if(button)button.disabled=true;try{essayResult=await apiFetch('/attempts/essay',{method:'POST',body:data});render()}catch(error){toast(error.message,'warning');if(button)button.disabled=false}}
app.addEventListener('click',e=>{const essayNav=e.target.closest('[data-page="essay"]');if(essayNav){setTimeout(loadEssaySet,0);return}if(e.target.closest('#essay-submit')){e.preventDefault();e.stopImmediatePropagation();submitEssayReal();return}if(e.target.closest('#essay-reset')){essayResult=null;render();return}},{capture:true});
app.addEventListener('change',e=>{if(e.target.id==='essay-upload'){const file=e.target.files[0];if(file){document.querySelector('#upload-name').textContent=file.name;const img=document.querySelector('#upload-preview');img.src=URL.createObjectURL(file);img.classList.remove('d-none')}}});
let managedUsers=[],usersLoading=false,usersError='';
function usersPage(){if(!state.sessionUser)return `${heading('Quản lý người dùng','Đăng nhập với tài khoản Admin hoặc Giáo viên.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;return `${heading(state.sessionUser.role==='ADMIN'?'Quản lý người dùng':'Học sinh của tôi','Tài khoản và học sinh được phân công.')}${usersError?`<div class="alert alert-warning">${htmlSafe(usersError)}</div>`:''}${state.sessionUser.role==='ADMIN'?`<div class="cardx card-pad mb-4"><h2 class="card-title mb-3">Tạo tài khoản</h2><form id="user-create-form" class="row g-2"><div class="col-md-4"><input class="form-control" name="fullName" placeholder="Họ và tên" required></div><div class="col-md-4"><input class="form-control" name="username" placeholder="Tên đăng nhập" required></div><div class="col-md-4"><input class="form-control" type="email" name="email" placeholder="Email" required></div><div class="col-md-4"><input class="form-control" type="password" name="password" placeholder="Mật khẩu (ít nhất 12 ký tự)" minlength="12" required></div><div class="col-md-4"><select class="form-select" name="role"><option value="TEACHER">Giáo viên</option><option value="STUDENT">Học sinh</option></select></div><div class="col-md-4"><input class="form-control" type="number" name="teacherId" placeholder="ID giáo viên phụ trách (nếu có)"></div><div class="col-12"><button class="btn btn-primary" type="submit">Tạo tài khoản</button></div></form></div>`:state.sessionUser.role==='TEACHER'?`<div class="cardx card-pad mb-4"><h2 class="card-title mb-3">Thêm học sinh vào lớp</h2><form id="teacher-student-create-form" class="row g-2"><div class="col-md-6"><input class="form-control" name="fullName" placeholder="Họ và tên học sinh" required></div><div class="col-md-6"><input class="form-control" type="email" name="email" placeholder="Email" required></div><div class="col-md-6"><input class="form-control" name="username" placeholder="Tên đăng nhập" required></div><div class="col-md-6"><input class="form-control" type="password" name="password" placeholder="Mật khẩu (ít nhất 12 ký tự)" minlength="12" required></div><div class="col-12"><button class="btn btn-primary" type="submit">Tạo tài khoản học sinh</button><span class="tiny muted ms-2">Học sinh sẽ tự động được gán cho bạn.</span></div></form></div>`:''}<div class="cardx"><div class="table-responsive"><table class="table"><thead><tr><th>Họ tên</th><th>Tên đăng nhập</th><th>Email</th><th>Vai trò</th><th>GV phụ trách</th><th>Trạng thái</th>${state.sessionUser.role==='ADMIN'?'<th></th>':''}</tr></thead><tbody>${usersLoading?'<tr><td colspan="7">Đang tải…</td></tr>':managedUsers.map(u=>`<tr><td>${htmlSafe(u.fullName)}</td><td>${htmlSafe(u.username)}</td><td>${htmlSafe(u.email)}</td><td>${htmlSafe(u.role)}</td><td>${u.teacherId??'—'} ${u.role==='STUDENT'&&state.sessionUser.role==='ADMIN'?`<button class="btn btn-light btn-sm" data-assign-user="${u.id}" data-current-teacher="${u.teacherId??''}">Phân công</button>`:''}</td><td><span class="tag ${u.status==='ACTIVE'?'tag-green':'tag-orange'}">${htmlSafe(u.status)}</span></td>${state.sessionUser.role==='ADMIN'?`<td><button class="btn btn-light btn-sm" data-user-id="${u.id}" data-user-status="${u.status==='ACTIVE'?'INACTIVE':'ACTIVE'}">${u.status==='ACTIVE'?'Tắt':'Kích hoạt'}</button></td>`:''}</tr>`).join('')||(!usersLoading?'<tr><td colspan="7" class="text-center muted">Chưa có người dùng.</td></tr>':'')}</tbody></table></div></div>`}
async function loadUsers(){if(!state.sessionUser)return;usersLoading=true;usersError='';render();try{managedUsers=await apiFetch('/users')}catch(error){usersError=error.message;managedUsers=[]}finally{usersLoading=false;render()}}
app.addEventListener('click',e=>{const usersNav=e.target.closest('[data-page="users"],[data-page="students"]');if(usersNav)setTimeout(loadUsers,0);const status=e.target.closest('[data-user-id]');if(status){e.preventDefault();e.stopImmediatePropagation();apiFetch(`/users/${status.dataset.userId}/status`,{method:'PATCH',body:JSON.stringify({status:status.dataset.userStatus})}).then(loadUsers).catch(error=>toast(error.message,'warning'))}},{capture:true});
function openTeacherAssignment(button){const studentId=Number(button.dataset.assignUser);const currentTeacher=button.dataset.currentTeacher;const teachers=managedUsers.filter(user=>user.role==='TEACHER'&&user.status==='ACTIVE');const modal=document.createElement('div');modal.className='modal fade';modal.tabIndex=-1;modal.setAttribute('aria-labelledby','teacher-assignment-title');modal.innerHTML='<div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5" id="teacher-assignment-title">Phân công giáo viên</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Đóng"></button></div><form id="teacher-assignment-form"><div class="modal-body"><label class="form-label" for="teacher-assignment-select">Giáo viên phụ trách</label><select class="form-select" id="teacher-assignment-select" name="teacherId"><option value="">Chưa phân công</option>'+teachers.map(t=>'<option value="'+t.id+'" '+(String(t.id)===currentTeacher?'selected':'')+'>'+htmlSafe(t.fullName)+' · '+htmlSafe(t.username)+'</option>').join('')+'</select>'+(teachers.length?'':'<div class="form-text">Chưa có giáo viên đang hoạt động để phân công.</div>')+'</div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Hủy</button><button type="submit" class="btn btn-primary" >Lưu phân công</button></div></form></div></div>';document.body.append(modal);const instance=bootstrap.Modal.getOrCreateInstance(modal);modal.addEventListener('hidden.bs.modal',()=>{instance.dispose();modal.remove()},{once:true});modal.querySelector('#teacher-assignment-form').addEventListener('submit',async event=>{event.preventDefault();const value=new FormData(event.currentTarget).get('teacherId');try{await apiFetch('/users/'+studentId+'/teacher',{method:'PUT',body:JSON.stringify({teacherId:value?Number(value):null})});instance.hide();toast('Đã cập nhật giáo viên phụ trách.');loadUsers()}catch(error){toast(error.message,'warning')}});instance.show()}
app.addEventListener('click',e=>{const button=e.target.closest('[data-assign-user]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();openTeacherAssignment(button)},{capture:true});
app.addEventListener('submit',e=>{if(e.target.id!=='user-create-form')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.teacherId=v.teacherId?Number(v.teacherId):null;apiFetch('/users',{method:'POST',body:JSON.stringify(v)}).then(()=>{toast('Đã tạo tài khoản.');e.target.reset();loadUsers()}).catch(error=>toast(error.message,'warning'))});
app.addEventListener('submit',e=>{if(e.target.id!=='teacher-student-create-form')return;e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form));apiFetch('/users/students',{method:'POST',body:JSON.stringify(values)}).then(()=>{toast('Đã tạo học sinh và phân công vào lớp của bạn.');form.reset();loadUsers()}).catch(error=>toast(error.message,'warning'))});
let managedQuestions=[],managedLessons=[],questionsLoading=false,questionsError='',questionEditing=null;
function questionsPage(){if(!state.sessionUser)return `${heading('Ngân hàng câu hỏi','Đăng nhập với vai trò Giáo viên hoặc Admin.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;return `${heading('Ngân hàng câu hỏi','Tạo câu hỏi, yêu cầu AI sinh bản nháp, sau đó duyệt trước khi xuất bản.')}${questionsError?`<div class="alert alert-warning">${htmlSafe(questionsError)}</div>`:''}<div class="row g-4"><div class="col-xl-5"><div class="cardx card-pad mb-4"><h2 class="card-title mb-3">Tạo câu hỏi thủ công</h2><form id="question-create-form"><label class="form-label">Bài học</label><select class="form-select mb-2" name="lessonId" required>${managedLessons.map(l=>`<option value="${l.id}">${htmlSafe(l.title)}</option>`).join('')}</select><div class="row g-2"><div class="col-6"><select class="form-select" name="type"><option value="MCQ">Trắc nghiệm</option><option value="ESSAY">Tự luận</option></select></div><div class="col-6"><select class="form-select" name="difficulty"><option value="EASY">Cơ bản</option><option value="MEDIUM">Trung bình</option><option value="HARD">Nâng cao</option></select></div></div><textarea class="form-control mt-2" name="text" rows="3" placeholder="Nội dung câu hỏi" required></textarea><div class="question-options mt-2"><input class="form-control mb-2" name="optionA" placeholder="Đáp án A"><input class="form-control mb-2" name="optionB" placeholder="Đáp án B"><input class="form-control mb-2" name="optionC" placeholder="Đáp án C"><input class="form-control mb-2" name="optionD" placeholder="Đáp án D"><select class="form-select mb-2" name="correctAnswer"><option value="A">Đáp án đúng: A</option><option value="B">Đáp án đúng: B</option><option value="C">Đáp án đúng: C</option><option value="D">Đáp án đúng: D</option></select></div><textarea class="form-control mt-2" name="solutionSteps" rows="3" placeholder="Lời giải từng bước"></textarea><button class="btn btn-primary w-100 mt-3">Lưu câu hỏi nháp</button></form></div><div class="cardx card-pad"><h2 class="card-title mb-3">Sinh câu hỏi nháp bằng AI</h2><form id="question-generate-form"><select class="form-select mb-2" name="lessonId" required>${managedLessons.map(l=>`<option value="${l.id}">${htmlSafe(l.title)}</option>`).join('')}</select><div class="row g-2"><div class="col-5"><select class="form-select" name="type"><option value="MCQ">Trắc nghiệm</option><option value="ESSAY">Tự luận</option></select></div><div class="col-4"><select class="form-select" name="difficulty"><option value="EASY">Cơ bản</option><option value="MEDIUM">Trung bình</option><option value="HARD">Nâng cao</option></select></div><div class="col-3"><input class="form-control" type="number" name="count" value="3" min="1" max="10" required></div></div><textarea class="form-control mt-2" name="instructions" rows="2" placeholder="Yêu cầu thêm (không bắt buộc)"></textarea><button class="btn btn-soft w-100 mt-3">Tạo bản nháp</button></form><p class="tiny muted mt-2 mb-0">Câu AI tạo luôn ở trạng thái chờ duyệt.</p></div></div><div class="col-xl-7"><div class="cardx card-pad"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="card-title">Câu hỏi đã lưu</h2><button class="btn btn-light btn-sm" id="questions-refresh">Làm mới</button></div>${questionsLoading?'<div>Đang tải…</div>':managedQuestions.map(q=>`<article class="border rounded-3 p-3 mb-3"><div class="d-flex justify-content-between"><span class="tag ${q.source==='AI'?'tag-purple':'tag-blue'}">${htmlSafe(q.type)} · ${htmlSafe(q.difficulty)} · ${htmlSafe(q.source)}</span><span class="tag ${q.status==='PUBLISHED'?'tag-green':'tag-orange'}">${htmlSafe(q.status)}</span></div><h3 class="mt-3" style="font-size:15px">${htmlSafe(q.text)}</h3>${q.type==='MCQ'?`<div class="small muted">A. ${htmlSafe(q.optionA)}<br>B. ${htmlSafe(q.optionB)}<br>C. ${htmlSafe(q.optionC)}<br>D. ${htmlSafe(q.optionD)}<br>Đáp án: ${htmlSafe(q.correctAnswer)}</div>`:''}<p class="small mt-2 mb-0">${htmlSafe(q.solutionSteps||q.explanation||'')}</p>${q.status!=='PUBLISHED'?`<button class="btn btn-primary btn-sm mt-3" data-publish-question="${q.id}">Duyệt và xuất bản</button>`:''}</article>`).join('')||(!questionsLoading?'<div class="muted">Chưa có câu hỏi thuộc các bài học bạn quản lý.</div>':'')}</div></div></div>`}
function pageView(){if(state.role==='student')return ({dashboard:dashboardStudent,lessons:lessonsStudent,'lesson-detail':lessonDetail,formulas:formulasPage,practice,essay:essayPage,'ai-tutor':aiTutorPage,history:historyPage,progress:progressPage}[state.page]||dashboardStudent)();if(state.role==='teacher')return ({dashboard:teacherDash,students:usersPage,topics:topicsPage,lessons:teacherLessons,questions:questionsPage,generator:questionsPage,progress:progressPage}[state.page]||teacherDash)();return ({dashboard:adminDashboard,users:usersPage,topics:topicsPage,lessons:teacherLessons,questions:questionsPage,settings:settingsPage}[state.page]||adminDashboard)()}
async function loadQuestions(){if(!state.sessionUser)return;questionsLoading=true;questionsError='';render();try{const [q,l]=await Promise.all([apiFetch('/manage/questions'),apiFetch('/manage/lessons')]);managedQuestions=q;managedLessons=l}catch(error){questionsError=error.message;managedQuestions=[];managedLessons=[]}finally{questionsLoading=false;render()}}
app.addEventListener('click',e=>{const link=e.target.closest('[data-page="questions"],[data-page="generator"]');if(link)setTimeout(loadQuestions,0);if(e.target.closest('#questions-refresh'))loadQuestions();const publish=e.target.closest('[data-publish-question]');if(publish){e.preventDefault();e.stopImmediatePropagation();apiFetch(`/questions/${publish.dataset.publishQuestion}/publish`,{method:'POST'}).then(()=>{toast('Đã xuất bản câu hỏi.');loadQuestions()}).catch(error=>toast(error.message,'warning'))}const edit=e.target.closest('[data-edit-question]');if(edit){e.preventDefault();e.stopImmediatePropagation();const q=managedQuestions.find(row=>row.id===Number(edit.dataset.editQuestion));if(!q)return;questionEditing=q.id;render();const form=document.querySelector('#question-create-form');for(const [key,value] of Object.entries({lessonId:q.lessonId,type:q.type,difficulty:q.difficulty,text:q.text,optionA:q.optionA,optionB:q.optionB,optionC:q.optionC,optionD:q.optionD,correctAnswer:q.correctAnswer,solutionSteps:q.solutionSteps})){if(form.elements[key])form.elements[key].value=value??''}document.querySelector('.question-options')?.classList.toggle('d-none',q.type==='ESSAY');form.scrollIntoView({behavior:'smooth'})}} ,{capture:true});
app.addEventListener('change',e=>{if(e.target.closest('#question-create-form')&&e.target.name==='type'){const essay=e.target.value==='ESSAY';document.querySelector('.question-options')?.classList.toggle('d-none',essay)}});
app.addEventListener('submit',e=>{if(e.target.id==='question-create-form'){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.lessonId=Number(v.lessonId);if(v.type==='ESSAY'){for(const k of ['optionA','optionB','optionC','optionD','correctAnswer'])v[k]=null}v.status='DRAFT';const editing=questionEditing;questionEditing=null;apiFetch(editing?`/questions/${editing}`:'/questions',{method:editing?'PUT':'POST',body:JSON.stringify(v)}).then(()=>{toast(editing?'Đã cập nhật câu hỏi.':'Đã lưu câu hỏi nháp.');e.target.reset();loadQuestions()}).catch(error=>toast(error.message,'warning'))}if(e.target.id==='question-generate-form'){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.lessonId=Number(v.lessonId);v.count=Number(v.count);apiFetch('/questions/generate',{method:'POST',body:JSON.stringify(v)}).then(rows=>{toast(`AI đã tạo ${rows.length} câu nháp.`);loadQuestions()}).catch(error=>toast(error.message,'warning'))}});
let topicsManaged=[],topicLoading=false,lessonEditing=null,topicEditing=null;
function teacherLessons(){if(!state.sessionUser)return `${heading('Bài giảng','Đăng nhập với vai trò Giáo viên hoặc Admin.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;return `${heading('Quản lý bài giảng','Tạo nội dung và tài nguyên học tập; bài nháp chưa hiển thị với học sinh.')}${questionsError?`<div class="alert alert-warning">${htmlSafe(questionsError)}</div>`:''}<div class="row g-4"><div class="col-xl-5"><div class="cardx card-pad"><h2 class="card-title mb-3">${lessonEditing?'Sửa bài giảng':'Tạo bài giảng'}</h2><form id="lesson-form"><label class="form-label">Chủ đề</label><select class="form-select mb-2" name="topicId" required>${topicsManaged.map(t=>`<option value="${t.id}">${htmlSafe(t.name)}</option>`).join('')}</select><input class="form-control mb-2" name="title" placeholder="Tên bài giảng" required><input class="form-control mb-2" name="description" placeholder="Mô tả ngắn"><textarea class="form-control mb-2" name="content" rows="7" placeholder="Nội dung bài giảng"></textarea><input class="form-control mb-2" type="url" name="videoUrl" placeholder="URL video (tùy chọn)"><input class="form-control mb-2" type="url" name="resourceUrl" placeholder="URL tài liệu (tùy chọn)"><div class="row g-2"><div class="col-6"><input class="form-control" type="number" name="order" value="1" min="1" required></div><div class="col-6"><select class="form-select" name="status"><option value="DRAFT">Bản nháp</option><option value="PUBLISHED">Xuất bản</option></select></div></div><button class="btn btn-primary mt-3">${lessonEditing?'Lưu thay đổi':'Tạo bài giảng'}</button>${lessonEditing?'<button class="btn btn-light mt-3 ms-2" type="button" id="lesson-cancel">Hủy sửa</button>':''}</form></div></div><div class="col-xl-7"><div class="cardx card-pad"><h2 class="card-title mb-3">Bài giảng của tôi</h2>${managedLessons.map(l=>`<article class="border rounded-3 p-3 mb-2"><div class="d-flex justify-content-between"><strong>${htmlSafe(l.title)}</strong><span class="tag tag-blue">${htmlSafe(topicsManaged.find(t=>t.id===l.topicId)?.name||'Chủ đề')}</span></div><p class="small muted mt-2">${htmlSafe(l.description||'')}</p><button class="btn btn-light btn-sm" data-edit-lesson="${l.id}">Chỉnh sửa</button></article>`).join('')||'<div class="muted">Chưa có bài giảng.</div>'}</div></div></div>`}
async function loadTeaching(){if(!state.sessionUser)return;questionsLoading=true;questionsError='';render();try{const [lessons,topics]=await Promise.all([apiFetch('/manage/lessons'),apiFetch('/topics')]);managedLessons=lessons;topicsManaged=topics}catch(error){questionsError=error.message;managedLessons=[];topicsManaged=[]}finally{questionsLoading=false;render()}}
function topicsPage(){if(!state.sessionUser)return `${heading('Chủ đề Toán 10','Đăng nhập với vai trò Admin hoặc Giáo viên.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;return `${heading('Chủ đề Toán 10','Tạo và sắp xếp nội dung theo chương trình Toán 10.')}${questionsError?`<div class="alert alert-warning">${htmlSafe(questionsError)}</div>`:''}<div class="cardx card-pad mb-4"><form id="topic-form" class="row g-2"><div class="col-md-4"><input class="form-control" name="name" placeholder="Tên chủ đề" required></div><div class="col-md-4"><input class="form-control" name="description" placeholder="Mô tả"></div><div class="col-md-2"><input class="form-control" type="number" name="order" min="1" value="1" required></div><div class="col-md-2"><button class="btn btn-primary w-100">${topicEditing?'Lưu thay đổi':'Thêm chủ đề'}</button></div></form></div><div class="row g-3">${topicsManaged.map(t=>`<div class="col-md-6 col-xl-4"><div class="cardx card-pad"><span class="tag tag-blue">CHỦ ĐỀ ${t.order}</span><h3 class="mt-3" style="font-size:16px">${htmlSafe(t.name)}</h3><p class="small muted">${htmlSafe(t.description||'')}</p><button class="btn btn-light btn-sm" data-edit-topic="${t.id}">Chỉnh sửa</button></div></div>`).join('')||'<div class="col-12 muted">Chưa có chủ đề.</div>'}</div>`}
async function loadTopicsManaged(){if(!state.sessionUser)return;questionsLoading=true;questionsError='';render();try{topicsManaged=await apiFetch('/manage/topics')}catch(error){questionsError=error.message;topicsManaged=[]}finally{questionsLoading=false;render()}}
app.addEventListener('click',e=>{const nav=e.target.closest('[data-page="lessons"],[data-page="topics"]');if(nav){lessonEditing=null;setTimeout(()=>{if(state.page==='topics')loadTopicsManaged();else if(state.role!=='student')loadTeaching()},0)}const edit=e.target.closest('[data-edit-lesson]');if(edit){const l=managedLessons.find(x=>x.id===Number(edit.dataset.editLesson));if(!l)return;lessonEditing=l.id;render();const form=document.querySelector('#lesson-form');for(const [key,value] of Object.entries({topicId:l.topicId,title:l.title,description:l.description,content:l.content,videoUrl:l.videoUrl,resourceUrl:l.resourceUrl,order:l.order,status:'DRAFT'})){if(form.elements[key])form.elements[key].value=value??''}form.scrollIntoView({behavior:'smooth'})}if(e.target.closest('#lesson-cancel')){lessonEditing=null;render()}},{capture:true});
app.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-topic]');if(!edit)return;e.preventDefault();e.stopImmediatePropagation();const topic=topicsManaged.find(t=>t.id===Number(edit.dataset.editTopic));if(!topic)return;topicEditing=topic.id;render();const form=document.querySelector('#topic-form');for(const [key,value] of Object.entries({name:topic.name,description:topic.description,order:topic.order})){if(form.elements[key])form.elements[key].value=value??''}form.scrollIntoView({behavior:'smooth'})},{capture:true});
app.addEventListener('submit',e=>{if(e.target.id==='lesson-form'){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.topicId=Number(v.topicId);v.order=Number(v.order);const path=lessonEditing?`/lessons/${lessonEditing}`:'/lessons';apiFetch(path,{method:lessonEditing?'PUT':'POST',body:JSON.stringify(v)}).then(()=>{toast('Đã lưu bài giảng.');lessonEditing=null;loadTeaching()}).catch(error=>toast(error.message,'warning'))}if(e.target.id==='topic-form'){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.order=Number(v.order);v.status='ACTIVE';const editing=topicEditing;topicEditing=null;apiFetch(editing?`/topics/${editing}`:'/topics',{method:editing?'PUT':'POST',body:JSON.stringify(v)}).then(()=>{toast(editing?'Đã cập nhật chủ đề.':'Đã thêm chủ đề.');e.target.reset();loadTopicsManaged()}).catch(error=>toast(error.message,'warning'))}});
let progressPayload=null,progressBusy=false,progressError='';
const freeTutor={question:'',turns:[],step:0,busy:false,error:'',imageMimeType:'',imageBase64:'',imagePreview:'',historyId:''};
function tutorHistoryKey(){const user=state.sessionUser;if(!user)return '';const identity=user.id??user.username??user.email;return `math10-ai-tutor-history:${String(identity).toLowerCase()}`}
function readTutorHistory(){try{const key=tutorHistoryKey();const items=key?JSON.parse(localStorage.getItem(key)||'[]'):[];return Array.isArray(items)?items:[]}catch{return []}}
function saveTutorHistory(){try{const key=tutorHistoryKey();if(!key||!freeTutor.question||!freeTutor.turns.length)return;const items=readTutorHistory().filter(item=>item.id!==freeTutor.historyId);items.unshift({id:freeTutor.historyId,question:freeTutor.question,turns:freeTutor.turns,updatedAt:new Date().toISOString()});localStorage.setItem(key,JSON.stringify(items.slice(0,20)))}catch{}}
function aiTutorHistoryMarkup(){const items=readTutorHistory();if(!items.length)return '';return `<section class="cardx card-pad mt-4"><div class="section-head"><div><h2 class="card-title">Bài đã hỏi gần đây</h2><div class="card-subtitle">Lưu trên trình duyệt này, riêng theo tài khoản</div></div></div><div class="list-group list-group-flush">${items.map(item=>`<button type="button" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center gap-3" data-tutor-history-id="${htmlSafe(item.id)}"><span class="text-truncate">${htmlSafe(item.question)}</span><small class="muted flex-shrink-0">${htmlSafe(new Date(item.updatedAt).toLocaleDateString('vi-VN'))} · Mở lại</small></button>`).join('')}</div><p class="tiny muted mt-3 mb-0">Lịch sử chỉ lưu đề chữ và lời giải; ảnh đề bài không được lưu.</p></section>`}
function aiTutorPage(){if(!state.sessionUser)return `${heading('Gia sư AI','Đăng nhập để gửi đề bài và nhận lời giải đầy đủ.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;return `${heading('Gia sư AI','Nhập đề hoặc gửi ảnh bài toán phổ thông; gia sư sẽ giải đầy đủ ngay sau khi nhận đề.')}${freeTutor.error?`<div class="alert alert-warning">${htmlSafe(freeTutor.error)}</div>`:''}${!freeTutor.question?`<div class="cardx card-pad"><form id="free-tutor-form"><label class="form-label">Đề bài Toán</label><textarea class="form-control" name="question" rows="5" placeholder="Nhập đề bài cần giải (có thể để trống nếu gửi ảnh)..." maxlength="10000"></textarea><label class="form-label mt-3">Hoặc gửi ảnh đề bài</label><input class="form-control" type="file" name="problemImage" accept="image/png,image/jpeg,image/webp"><div class="tiny muted mt-2">PNG, JPG hoặc WEBP · Tối đa 5 MB.</div><button class="btn btn-primary mt-3" ${freeTutor.busy?'disabled':''}>Giải bài →</button></form></div>`:`<div class="row justify-content-center"><div class="col-xl-8"><div class="cardx card-pad"><div class="tag tag-purple">BÀI TOÁN CỦA BẠN</div><p class="mt-3 mb-4">${htmlSafe(freeTutor.question==='Giải bài toán trong ảnh đính kèm.'?'Đề bài trong ảnh':freeTutor.question)}</p>${freeTutor.imagePreview?`<img class="tutor-problem-image mb-3" src="${freeTutor.imagePreview}" alt="Ảnh đề toán đã gửi">`:''}${freeTutor.turns.map(t=>`<div class="tutor-bubble mb-3"><div class="tutor-head"><strong>${t.action==='CLARIFICATION'?'Cần làm rõ đề bài':'Lời giải đầy đủ'}</strong></div>${tutorMessageHtml(t.message)}</div>`).join('')}${freeTutor.busy?'<div class="alert alert-light">Gia sư đang giải bài…</div>':''}${freeTutor.error&&!freeTutor.turns.length?'<button class="btn btn-primary mt-2" id="free-tutor-retry">Thử lại</button>':''}${freeTutor.turns.length&&!freeTutor.busy&&!freeTutor.error?'<div class="alert alert-success mt-3">Gia sư đã trả lời xong.</div>':''}<button class="btn btn-light mt-3" id="free-tutor-reset">Gửi bài khác</button></div></div></div>`}${aiTutorHistoryMarkup()}<div class="tiny muted mt-3">Đề chữ và ảnh chỉ được gửi tới dịch vụ AI qua backend để tạo lời giải.</div>`}
function tutorImageData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('Không đọc được tệp ảnh.'));reader.readAsDataURL(file)})}
async function askGeneralTutor(input,first=false,attachment=null){if(first){freeTutor.question=input;freeTutor.turns=[];freeTutor.step=1;freeTutor.historyId=crypto.randomUUID?.()||String(Date.now())+'-'+Math.random().toString(36).slice(2);if(attachment){freeTutor.imageMimeType=attachment.mimeType;freeTutor.imageBase64=attachment.base64;freeTutor.imagePreview=attachment.dataUrl}}else freeTutor.step++;freeTutor.busy=true;freeTutor.error='';render();try{const response=await apiFetch('/tutor/ask',{method:'POST',body:JSON.stringify({question:freeTutor.question,studentInput:first?null:input,previousTurns:'',stepNumber:freeTutor.step,imageMimeType:first?(freeTutor.imageMimeType||null):null,imageBase64:first?(freeTutor.imageBase64||null):null})});freeTutor.turns.push({step:response.stepNumber,input:first?'':input,message:response.message,action:response.action});saveTutorHistory();if(response.finalStep)freeTutor.step=3}catch(error){freeTutor.error=error.message;if(!first)freeTutor.step--}finally{freeTutor.busy=false;render()}}
app.addEventListener('submit',e=>{if(e.target.id==='free-tutor-form'){e.preventDefault();const form=e.target,question=new FormData(form).get('question').trim(),file=form.elements.problemImage.files[0];if(!question&&!file){toast('Nhập đề bài hoặc chọn ảnh đề bài.','warning');return}if(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Chỉ hỗ trợ ảnh PNG, JPG hoặc WEBP.','warning');return}if(file.size>5*1024*1024){toast('Ảnh đề bài tối đa 5 MB.','warning');return}tutorImageData(file).then(dataUrl=>askGeneralTutor(question||'Giải bài toán trong ảnh đính kèm.',true,{mimeType:file.type,base64:dataUrl.split(',')[1],dataUrl})).catch(error=>toast(error.message,'warning'))}else askGeneralTutor(question,true)}if(e.target.id==='free-tutor-step-form'){e.preventDefault();const input=new FormData(e.target).get('studentInput').trim();if(input)askGeneralTutor(input,false)}});
app.addEventListener('click',e=>{const saved=e.target.closest('[data-tutor-history-id]');if(saved){const item=readTutorHistory().find(entry=>entry.id===saved.dataset.tutorHistoryId);if(item){freeTutor.question=item.question;freeTutor.turns=item.turns||[];freeTutor.historyId=item.id;freeTutor.step=freeTutor.turns.length;freeTutor.error='';freeTutor.imagePreview='';freeTutor.imageBase64='';freeTutor.imageMimeType='';render()}return}if(e.target.closest('#free-tutor-reset')){freeTutor.question='';freeTutor.turns=[];freeTutor.step=0;freeTutor.error='';freeTutor.imageMimeType='';freeTutor.imageBase64='';freeTutor.imagePreview='';render()}},{capture:true});
app.addEventListener('click',e=>{if(e.target.closest('#free-tutor-retry')){const attachment=freeTutor.imageBase64?{mimeType:freeTutor.imageMimeType,base64:freeTutor.imageBase64,dataUrl:freeTutor.imagePreview}:null;askGeneralTutor(freeTutor.question,true,attachment)}},{capture:true});
function progressPage(){if(!state.sessionUser)return `${heading('Tiến độ học tập','Đăng nhập để xem tiến độ được lưu từ các bài làm.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;if(progressBusy)return `${heading('Tiến độ học tập','Đang tải dữ liệu thật từ SQL Server.')}<div class="cardx card-pad">Đang tải…</div>`;if(progressError)return `${heading('Tiến độ học tập','') }<div class="alert alert-warning">${htmlSafe(progressError)}</div>`;if(state.sessionUser.role==='TEACHER')return `${heading('Kết quả học tập','Chỉ hiển thị học sinh được phân công cho bạn.') }<div class="cardx"><div class="table-responsive"><table class="table"><thead><tr><th>Học sinh</th><th>Số bài làm</th><th>Đúng</th><th>Độ chính xác</th><th>Điểm TB</th></tr></thead><tbody>${(progressPayload||[]).map(s=>`<tr><td>${htmlSafe(s.fullName)}</td><td>${s.attempts}</td><td>${s.correct}</td><td>${s.accuracy.toFixed(1)}%</td><td>${s.averageScore.toFixed(1)}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có dữ liệu học tập.</td></tr>'}</tbody></table></div></div>`;if(state.sessionUser.role==='ADMIN'){const s=progressPayload||{};return `${heading('Tiến độ hệ thống','Tổng hợp bài làm đã lưu.') }<div class="row g-3">${metric('Tổng bài làm',s.attempts||0,'Tất cả học sinh','chart')}${metric('Câu trả lời đúng',s.correct||0,'Đã chấm tự động','check','green')}${metric('Độ chính xác',`${(s.accuracy||0).toFixed(1)}%`,'Tỷ lệ trên bài trắc nghiệm','chart','purple')}${metric('Điểm trung bình',(s.averageScore||0).toFixed(1),'Trên thang điểm 10','grid','orange')}</div>`}const p=progressPayload||{};return `${heading('Tiến độ học tập','Kết quả tổng hợp từ các lần luyện tập đã lưu.') }<div class="row g-3 mb-4">${metric('Bài đã làm',p.summary?.attempts||0,'Tổng lượt nộp','quiz')}${metric('Câu đúng',p.summary?.correct||0,'Được chấm chính xác','check','green')}${metric('Độ chính xác',`${(p.summary?.accuracy||0).toFixed(1)}%`,'Theo bài trắc nghiệm','chart','purple')}${metric('Điểm trung bình',(p.summary?.averageScore||0).toFixed(1),'Trên thang điểm 10','grid','orange')}</div><div class="cardx card-pad"><h2 class="card-title mb-3">Theo chủ đề</h2>${(p.topics||[]).map(t=>`<div class="mb-3"><div class="d-flex justify-content-between"><strong>${htmlSafe(t.topicName)}</strong><span>${t.correct}/${t.attempts} đúng · ${t.accuracy.toFixed(1)}%</span></div><div class="progress mt-2"><div class="progress-bar" style="width:${Math.min(100,t.accuracy)}%"></div></div></div>`).join('')||'<span class="muted">Chưa có dữ liệu theo chủ đề.</span>'}</div>`}
async function loadProgress(){if(!state.sessionUser)return;progressBusy=true;progressError='';render();try{progressPayload=state.sessionUser.role==='STUDENT'?await apiFetch('/progress/mine'):state.sessionUser.role==='TEACHER'?await apiFetch('/progress/students'):await apiFetch('/progress')}catch(error){progressError=error.message}finally{progressBusy=false;render()}}
app.addEventListener('click',e=>{if(e.target.closest('[data-page="progress"]'))setTimeout(loadProgress,0)},{capture:true});
let aiConfigStatus=null,aiTestResult='';
function settingsPage(){if(!state.sessionUser||state.sessionUser.role!=='ADMIN')return `${heading('Cấu hình AI','Chỉ quản trị viên mới xem được trạng thái cấu hình.')}<button class="btn btn-primary" id="auth-open">Đăng nhập Admin</button>`;const s=aiConfigStatus||{};return `${heading('Cấu hình AI','API key được cấu hình ở máy chủ bằng biến môi trường; trình duyệt không nhận hoặc lưu khóa.') }<div class="row g-4"><div class="col-xl-7"><div class="cardx card-pad"><h2 class="card-title">Nhà cung cấp</h2><div class="d-flex justify-content-between mt-4"><span>Loại kết nối</span><strong>${htmlSafe(s.provider||'Đang tải trạng thái…')}</strong></div><div class="d-flex justify-content-between mt-3"><span>Model</span><strong>${htmlSafe(s.model||'—')}</strong></div><div class="d-flex justify-content-between mt-3"><span>API key</span><span class="tag ${s.apiKeyConfigured?'tag-green':'tag-orange'}">${s.apiKeyConfigured?'Đã cấu hình ở máy chủ':'Chưa cấu hình'}</span></div><div class="alert alert-light border small mt-4">Đặt <code>AI_API_URL</code>, <code>AI_API_KEY</code> và <code>AI_MODEL</code> trong môi trường chạy backend rồi khởi động lại ứng dụng. Khóa không được ghi vào SQL Server hay source code.</div><button class="btn btn-primary" id="ai-test">Kiểm tra kết nối</button>${aiTestResult?`<div class="alert alert-info mt-3 mb-0">${htmlSafe(aiTestResult)}</div>`:''}</div></div><div class="col-xl-5"><div class="cardx card-pad">${section('Gia sư từng bước')}<label class="form-label">Số lượt gợi ý trước khi hiện lời giải</label><input class="form-control" value="${htmlSafe(window.MATH10_HINT_LIMIT||3)}" disabled><p class="tiny muted mt-2">Thiết lập máy chủ qua AI_HINT_LIMIT.</p><div class="alert alert-primary small mb-0">Khi học sinh trả lời sai, backend lưu từng lượt và yêu cầu học sinh tiếp tục bằng phép tính/bước giải tiếp theo.</div></div></div></div>`}
async function loadAiStatus(){if(!state.sessionUser||state.sessionUser.role!=='ADMIN')return;try{aiConfigStatus=await apiFetch('/admin/ai/status');render()}catch(error){aiTestResult=error.message;render()}}
app.addEventListener('click',e=>{if(e.target.closest('[data-page="settings"]'))setTimeout(loadAiStatus,0);if(e.target.closest('#ai-test')){e.preventDefault();e.stopImmediatePropagation();apiFetch('/admin/ai/test',{method:'POST'}).then(r=>{aiTestResult=`Kết nối thành công: ${r.message}`;render()}).catch(error=>{aiTestResult=error.message;render()})}},{capture:true});
let dashboardPayload=null,dashboardLoading=false,dashboardError='';
function dashboardStudent(){if(!state.sessionUser)return `${heading('Chào mừng đến Math10 AI','Đây là chế độ xem thử. Đăng nhập để lưu kết quả học tập và luyện với AI.') }<div class="row g-3 mb-4">${metric('Bài học','—','Dữ liệu từ SQL Server sau khi đăng nhập','book')}${metric('Bài luyện tập','—','Lưu vào lịch sử cá nhân','quiz','green')}${metric('Gia sư AI','—','Gợi ý theo từng bước','spark','purple')}</div><button class="btn btn-primary" id="auth-open">Đăng nhập để học</button><button class="btn btn-light ms-2" data-page="lessons">Xem bài học mẫu</button>`;if(dashboardLoading)return `${heading('Tổng quan học tập','Đang tải dữ liệu tài khoản.') }<div class="cardx card-pad">Đang tải…</div>`;const p=dashboardPayload?.summary||{};const lessons=catalogLessons().slice(0,3);return `${heading(`Chào ${htmlSafe(state.sessionUser.fullName)} `,'Tiến độ thật từ các bài làm đã lưu.')}${dashboardError?`<div class="alert alert-warning">${htmlSafe(dashboardError)}</div>`:''}<div class="row g-3 mb-4">${metric('Bài đã làm',p.attempts||0,'Tổng lượt nộp','quiz')}${metric('Câu đúng',p.correct||0,'Được chấm tự động','check','green')}${metric('Độ chính xác',`${(p.accuracy||0).toFixed(1)}%`,'Trên câu đã chấm','chart','purple')}${metric('Điểm trung bình',(p.averageScore||0).toFixed(1),'Trên thang điểm 10','grid','orange')}</div><div class="cardx card-pad">${section('Bài học','Nội dung được tải từ API',`<a href="#lessons" data-page="lessons">Tất cả bài học →</a>`)}<div class="row g-3">${lessons.map((l,i)=>`<div class="col-md-4"><article class="border rounded-3 p-3 h-100"><span class="tag tag-blue">${htmlSafe(l.topicName)}</span><h3 class="mt-3" style="font-size:15px">${htmlSafe(l.title)}</h3><button class="btn btn-soft w-100 mt-2" data-page="lesson-detail" data-lesson-id="${l.id}">Mở bài học</button></article></div>`).join('')||'<div class="muted">Chưa có bài học đang xuất bản.</div>'}</div></div>`}
function teacherDash(){if(!state.sessionUser)return `${heading('Không gian giáo viên','Đăng nhập để quản lý lớp và nội dung.')}<button class="btn btn-primary" id="auth-open">Đăng nhập</button>`;const rows=dashboardPayload?.students||[];return `${heading(`Xin chào ${htmlSafe(state.sessionUser.fullName)}`,'Theo dõi học sinh được phân công và nội dung giảng dạy.')}${dashboardError?`<div class="alert alert-warning">${htmlSafe(dashboardError)}</div>`:''}<div class="row g-3 mb-4">${metric('Học sinh được giao',dashboardPayload?.users?.length||0,'Tài khoản trong lớp','users')}${metric('Bài giảng',dashboardPayload?.lessons?.length||0,'Bài của bạn','book','green')}${metric('Câu hỏi',dashboardPayload?.questions?.length||0,'Ngân hàng bạn quản lý','quiz','orange')}${metric('Lượt học',rows.reduce((n,s)=>n+s.attempts,0),'Từ dữ liệu đã lưu','chart','purple')}</div><div class="cardx card-pad">${section('Tiến độ học sinh','Chỉ học sinh được phân công') }<div class="table-responsive"><table class="table"><thead><tr><th>Học sinh</th><th>Bài làm</th><th>Độ chính xác</th><th>Điểm TB</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${htmlSafe(s.fullName)}</td><td>${s.attempts}</td><td>${s.accuracy.toFixed(1)}%</td><td>${s.averageScore.toFixed(1)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">Chưa có học sinh được phân công hoặc bài làm.</td></tr>'}</tbody></table></div><button class="btn btn-primary" data-page="lessons">Quản lý bài giảng</button></div>`}
function adminDashboard(){if(!state.sessionUser)return `${heading('Quản trị Math10 AI','Đăng nhập Admin để quản lý hệ thống.')}<button class="btn btn-primary" id="auth-open">Đăng nhập Admin</button>`;const p=dashboardPayload||{};return `${heading(`Xin chào ${htmlSafe(state.sessionUser.fullName)}`,'Tổng quan lấy từ database và trạng thái AI.')}${dashboardError?`<div class="alert alert-warning">${htmlSafe(dashboardError)}</div>`:''}<div class="row g-3 mb-4">${metric('Người dùng',p.users?.length||0,'Tài khoản','users')}${metric('Chủ đề',p.topics?.length||0,'Đang hoạt động','grid','green')}${metric('Bài giảng',p.lessons?.length||0,'Bao gồm bản nháp','book','orange')}${metric('Câu hỏi',p.questions?.length||0,'Ngân hàng câu hỏi','quiz','purple')}</div><div class="row g-3"><div class="col-md-6"><div class="cardx card-pad"><strong>AI Provider</strong><div class="mt-2">${htmlSafe(p.ai?.provider||'Chưa kiểm tra')}</div><div class="tiny muted">Model: ${htmlSafe(p.ai?.model||'—')}</div><button class="btn btn-light mt-3" data-page="settings">Cấu hình AI</button></div></div><div class="col-md-6"><div class="cardx card-pad"><strong>Hoạt động học tập</strong><div class="mt-2">${p.progress?.attempts||0} lượt làm · độ chính xác ${(p.progress?.accuracy||0).toFixed(1)}%</div><button class="btn btn-light mt-3" data-page="progress">Xem tiến độ</button></div></div></div>`}
async function loadDashboard(){if(!state.sessionUser)return;dashboardLoading=true;dashboardError='';render();try{if(state.sessionUser.role==='STUDENT')dashboardPayload=await apiFetch('/progress/mine');else if(state.sessionUser.role==='TEACHER'){const [students,users,lessons,questions]=await Promise.all([apiFetch('/progress/students'),apiFetch('/users'),apiFetch('/manage/lessons'),apiFetch('/manage/questions')]);dashboardPayload={students,users,lessons,questions}}else{const [users,topics,lessons,questions,progress,ai]=await Promise.all([apiFetch('/users'),apiFetch('/manage/topics'),apiFetch('/manage/lessons'),apiFetch('/manage/questions'),apiFetch('/progress'),apiFetch('/admin/ai/status')]);dashboardPayload={users,topics,lessons,questions,progress,ai}}}catch(error){dashboardError=error.message}finally{dashboardLoading=false;render()}}
app.addEventListener('click',e=>{if(e.target.closest('[data-page="dashboard"]'))setTimeout(loadDashboard,0)},{capture:true});
async function startPractice(){if(!state.sessionUser){toast('Đăng nhập để bắt đầu luyện tập.','warning');openLogin();return}const lesson=state.selectedLessonId||catalogLessons().find(x=>x.id)?.id;if(!lesson){toast('Không xác định được bài học để luyện tập.','warning');return}practiceLoading=true;practiceSubmitting=false;practiceQuestions=[];practiceIndex=0;practiceAttempt=null;practiceTutor=null;practiceError='';state.page='practice';render();try{const questions=await apiFetch(`/lessons/${lesson}/questions`);practiceQuestions=questions.filter(q=>q.type==='MCQ');if(!practiceQuestions.length)practiceError='Bài học chưa có câu trắc nghiệm đã xuất bản.'}catch(error){practiceError=error.message}finally{practiceLoading=false;render()}}
async function submitPractice(){if(state.selectedAnswer===null||practiceSubmitting||practiceAttempt)return;const q=practiceQuestions[practiceIndex];if(!q)return;practiceSubmitting=true;render();try{practiceAttempt=await apiFetch('/attempts',{method:'POST',body:JSON.stringify({questionId:q.id,answerText:'ABCD'[state.selectedAnswer]})});practiceTutor=null}catch(error){toast(error.message,'warning')}finally{practiceSubmitting=false;render()}}
async function continueTutor(){const input=document.querySelector('#tutor-step-input')?.value?.trim();if(!input){toast('Nhập bước tính tiếp theo trước nhé.','warning');return}try{practiceTutor=await apiFetch(`/attempts/${practiceAttempt.id}/tutor-turn`,{method:'POST',body:JSON.stringify({studentInput:input})});if(practiceTutor.action==='CONFIRM'||practiceTutor.action==='FINAL_SOLUTION')practiceAttempt.correct=Boolean(practiceTutor.correct);render()}catch(error){toast(error.message,'warning')}}
async function loadHistory(){if(!state.sessionUser)return;historyLoading=true;render();try{historyData=await apiFetch('/attempts/mine')}catch(error){historyData=[];toast(error.message,'warning')}finally{historyLoading=false;render()}}
app.addEventListener('click',e=>{const picked=e.target.closest('[data-answer]');if(picked&&state.page==='practice'){e.preventDefault();e.stopImmediatePropagation();if(practiceSubmitting||practiceAttempt)return;state.selectedAnswer=Number(picked.dataset.answer);submitPractice();return}const nav=e.target.closest('[data-page="practice"]');if(nav){e.preventDefault();e.stopImmediatePropagation();startPractice();return}if(e.target.closest('#submit-answer')){e.preventDefault();e.stopImmediatePropagation();submitPractice();return}if(e.target.closest('#next-question')){e.preventDefault();e.stopImmediatePropagation();practiceIndex++;practiceAttempt=null;practiceTutor=null;practiceSubmitting=false;state.selectedAnswer=null;render();return}if(e.target.closest('#mock-next-q')){e.preventDefault();e.stopImmediatePropagation();toast('Bạn đang ở chế độ xem thử. Đăng nhập để luyện tập đầy đủ 27 bài học SGK!');return}if(e.target.closest('#send-tutor-step')){e.preventDefault();e.stopImmediatePropagation();continueTutor();return}const historyLink=e.target.closest('[data-page="history"]');if(historyLink){setTimeout(loadHistory,0)}},{capture:true});
function updateGlobalSearch(value){const box=app.querySelector('#search-results');if(!box)return;const query=String(value||'').trim().toLocaleLowerCase('vi');if(query.length<2){box.innerHTML='';box.classList.add('d-none');return}const lessons=catalogLessons().filter(item=>(item.title+' '+item.topicName+' '+(item.description||'')).toLocaleLowerCase('vi').includes(query)).slice(0,6);const topics=(catalog.online?catalog.topics.map(t=>t.name):[...new Set(fallbackLessons.map(l=>l.topicName))]).filter(name=>name.toLocaleLowerCase('vi').includes(query)).slice(0,3);const items=[...lessons.map(l=>'<button type="button" class="search-result" role="option" data-search-lesson="'+htmlSafe(l.id)+'"><span class="tag tag-blue">Bài học</span><span class="search-result-copy"><strong>'+htmlSafe(l.title)+'</strong><small>'+htmlSafe(l.topicName)+'</small></span></button>'),...topics.map(name=>'<button type="button" class="search-result" role="option" data-search-topic="'+htmlSafe(name)+'"><span class="tag tag-purple">Chủ đề</span><span class="search-result-copy"><strong>'+htmlSafe(name)+'</strong><small>Xem các bài thuộc chủ đề</small></span></button>')];box.innerHTML=items.join('')||'<div class="search-empty">Không tìm thấy bài học hoặc chủ đề phù hợp.</div>';box.classList.remove('d-none')}
app.addEventListener('input',e=>{if(e.target.id==='global-search')updateGlobalSearch(e.target.value)});
app.addEventListener('focusin',e=>{if(e.target.id==='global-search'&&e.target.value)updateGlobalSearch(e.target.value)});
app.addEventListener('keydown',e=>{if(e.target.id!=='global-search')return;if(e.key==='Escape')app.querySelector('#search-results')?.classList.add('d-none');if(e.key==='Enter'){const first=app.querySelector('#search-results .search-result');if(first){e.preventDefault();first.click()}}});
app.addEventListener('click',e=>{const result=e.target.closest('[data-search-lesson],[data-search-topic]');if(!result)return;e.preventDefault();e.stopImmediatePropagation();if(result.dataset.searchLesson){state.selectedLessonId=Number(result.dataset.searchLesson);state.page='lesson-detail';render();window.scrollTo(0,0);return}const topic=result.dataset.searchTopic;state.page='lessons';render();setTimeout(()=>{const filter=[...app.querySelectorAll('.topic-filter')].find(button=>button.dataset.topic===topic);filter?.click()},0)},{capture:true});
document.addEventListener('click',e=>{if(!e.target.closest('.searchbox'))app.querySelector('#search-results')?.classList.add('d-none')});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!e.target.closest('input,textarea,select,[contenteditable="true"]')){const input=app.querySelector('#global-search');if(input){e.preventDefault();const box=app.querySelector('.searchbox');if(window.matchMedia('(max-width: 800px)').matches){box?.classList.add('mobile-open');app.querySelector('#search-toggle')?.setAttribute('aria-expanded','true')}input.focus();input.select()}}});

let pageTransitionActive=false;
function smoothPageTransition(change){if(pageTransitionActive||typeof document.startViewTransition!=='function'){change();return}pageTransitionActive=true;try{const transition=document.startViewTransition(()=>change());transition.finished.then(()=>{pageTransitionActive=false},()=>{pageTransitionActive=false})}catch{pageTransitionActive=false;change()}}
function pageAllowed(role,page){return roles[role]?.nav.some(([key])=>key===page)||role==='student'&&['essay','lesson-detail'].includes(page)}
function pageFromHash(){const route=decodeURIComponent(window.location.hash.slice(1)||'dashboard');if(route==='lesson-detail'&&!state.selectedLessonId)return 'lessons';const known=Object.values(roles).some(role=>role.nav.some(([key])=>key===route))||['essay','lesson-detail'].includes(route);return known?route:'dashboard'}
function loadPageData(page){if(!state.sessionUser)return;if(page==='dashboard')loadDashboard();else if(page==='practice')startPractice();else if(page==='essay')loadEssaySet();else if(page==='history')loadHistory();else if(page==='progress')loadProgress();else if(page==='settings')loadAiStatus()}
function syncRouteFromLocation(){const page=pageFromHash();if(window.location.hash!=='#'+page)history.replaceState({page},'',window.location.pathname+window.location.search+'#'+page);if(page===state.page)return;state.page=page;state.selectedAnswer=null;render();window.scrollTo({top:0,behavior:'smooth'});loadPageData(page)}
window.addEventListener('hashchange',syncRouteFromLocation);
window.addEventListener('popstate',syncRouteFromLocation);
state.page=pageFromHash();
if(window.location.hash!=='#'+state.page)history.replaceState({page:state.page},'',window.location.pathname+window.location.search+'#'+state.page);
render();
loadCatalog();
restoreSession();
